(window.GIM_TS=window.GIM_TS||{})["Bava Batra.9"]={"from":216,"a":[["\u0003אלא\u0004 כך יש ליישב את הדברים: \u0003אי אבוה דאמיה\u0004 \u0005[אם אביה של אמו\u0006 של פנחס\u0005]\u0006 היה \u0003מיוסף\u0004 — \u0003אמה דאמיה\u0004 \u0005[של אמו]\u0006 היתה \u0003מיתרו, אי אבוה דאמיה\u0004 \u0005[אם אביה של אמו]\u0006 היה \u0003מיתרו\u0004 — \u0003אמה דאמיה\u0004 \u0005[של אמו]\u0006 היתה \u0003מיוסף,\u0004 כלומר, שאמו היתה גם מצאצאי יוסף וגם מצאצאי יתרו. ואומרים: \u0003דיקא נמי\u0004 \u0005[מדוייק\u0006 הדבר \u0005גם כן]\u0006 מן הכתוב, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מבנות פוטיאל\", תרתי שמע מינה\u0004 \u0005[שתים אתה שומע מכאן]\u0006 שאכן, מבנות שני אנשים המכונים \"פוטי\" בא פינחס.","ועוד בענין זה \u0003אמר רבא: הנושא אשה צריך שיבדוק\u0004 תחילה \u0003באחיה,\u0004 ועל ידי כך יוכל לדעת מראש מה יהיה טיבם של בניו. \u0003שנאמר: \"ויקח אהרן את אלישבע בת עמינדב אחות נחשון\"\u0004 (שמות ו, כג), \u0003ממשמע שנאמר \"בת עמינדב\", איני יודע שאחות נחשון היא?\u0004 שהרי נחשון היה בן עמינדב! \u0003מה תלמוד לומר \"אחות נחשון\"? מכאן, שהנושא אשה צריך שיבדוק באחיה.\u0004 ובענין זה גם \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003רוב בנים דומין לאחי האם.\u0004 אגב זה שהזכרנו את המעשה ביהונתן ששימש ככהן לפסל מיכה, מביאים עוד מהדברים שפירשו חכמים בענין.","כאשר עברו בני שבט דן דרך בית מיכה נאמר: \u0003\"ויסורו שמה ויאמר מי הביאך הלם ומה אתה עושה בזה ומה לך פה\"\u0004 (שופטים יח, ג), ומסבירים את ריבוי הלשונות. \u0003אמרו לו\u0004 בני שבט דן: \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003ממשה קא אתית\u0004 \u0005[אתה בא]\u0006 \u0003דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006 \u0003\"אל תקרב הלם\"\u0004 (שמות ג, ה)? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003ממשה קא אתית\u0004 \u0005[אתה בא]\u0006 \u0003דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006 \u0003\"מה זה בידך\"\u0004 (שמות ד, ב)? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003ממשה קא אתית\u0004 \u0005[אתה בא]\u0006 \u0003דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006 \u0003\"ואתה פה עמד עמדי\"\u0004 (דברים ה, כח)? ואתה נכדו של משה רבינו \u0003תעשה כומר לעבודה זרה?!\u0004","\u0003אמר להן, כך מקובלני מבית אבי אבא: לעולם ישכיר אדם עצמו לעבודה זרה ואל יצטרך לבריות\u0004 לקבל מהם צדקה.","ומעירים: \u0003והוא\u0004 יהונתן בן גרשום \u0003סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 שהכוונה היא שישכיר עצמו \u0003לעבודה זרה ממש,\u0004 ומכיון שהיה עני השכיר עצמו לעבודה זרה של מיכה. \u0003ולא היא,\u0004 לא זו הכוונה, \u0003אלא עבודה זרה\u0004 כוונתה \u0003עבודה שזרה לו,\u0004 שאף על פי שמדובר בעבודה קשה ובזויה בעיניו, מוטב לאדם לעשותה ולא להזדקק לבריות, \u0003כדאמר ליה\u0004 \u0005[כפי שאמר לו]\u0006 \u0003רב לרב כהנא\u0004 תלמידו: \u0003נטוש נבילתא בשוקא\u0004 \u0003ושקול אגרא\u0004 \u0005[פשוט נבילה בשוק וטול שכר\u0006 עבור כך\u0005],\u0006 \u0003ולא תימא\u0004 \u0005[ואל תאמר]:\u0006 \u0003גברא רבא אנא וזילא בי מילתא\u0004 \u0005[אדם גדול אני ומזולזל עבורי הדבר],\u0006 אלא מוטב שתעבוד אפילו עבודה בזויה ולא תצטרך לבריות.","ובהמשך למסופר על יהונתן בן גרשום, מוסיפים: לאחר זמן רב, \u0003כיון שראה דוד שממון חביב עליו ביותר, מינהו על האוצרות, שנאמר\u0004 ברשימת הלויים שמינה דוד על אוצרות המקדש: \u0003\"ושבאל בן גרשם בן מנשה נגיד על האצרות\"\u0004 (דברי הימים א כו, כד), אגב כך תמהים: \u0003וכי שבואל שמו? והלא יהונתן שמו! אמר\u0004 \u0003ר' יוחנן:\u0004 טעם הדבר שקראוהו שבואל — כדי לרמז \u0003ששב לאל בכל לבו.\u0004","שנינו במשנה ש\u0003הבנים\u0004 יורשים \u0003את האב.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה שהבנים יורשים הכל ואין הבנות שותפות עימם? ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בפרשת נחלות: \u0003\"איש כי ימות\u0004 ובן אין לו והעברתם את נחלתו לבתו\u0003\"\u0004 (במדבר כז, ח), ומכאן יש לדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 במקרה ש\u0003אין לו בן, הא\u0004 \u0005[הרי]\u0006 אם \u0003יש לו בן\u0004 — ה\u0003בן קודם\u0004 לירושה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי, אימא\u0004 \u0005[אמור\u0006 כך\u0005]\u0006 את דיוק הכתוב: \u0003אי איכא\u0004 \u0005[אם יש]\u0006 רק \u0003בן\u0004 — \u0003לירות\u0004 \u0005[יירש]\u0006 ה\u0003בן,\u0004 אם \u0003איכא\u0004 \u0005[יש]\u0006 רק \u0003בת\u0004 — \u0003תירות\u0004 \u0005[תירש]\u0006 ה\u0003בת, איכא\u0004 \u0005[יש]\u0006 \u0003בן ובת\u0004 יחד — \u0003לא האי לירות\u0004 \u0005[זה יירש]\u0006 \u0003ולא האי לירות\u0004 \u0005[זה יירש]!\u0006","ותהה אביי על כך: \u0003ואלא\u0004"],["\u0003מאן לירות\u0004 \u0005[מי יירש]?\u0006 \u0003אטו בר קשא דמתא לירות\u0004 \u0005[וכי מושל העיר\u0006 הוא זה ש\u0005יירש]?!\u0006 אמר לו רב פפא: \u0003הכי קא אמינא\u0004 \u0005[כך אמרתי]:\u0006 אם \u0003איכא\u0004 \u0005[יש]\u0006 \u0003בן ובת\u0004 — \u0003לא האי לירות כוליה\u0004 \u0005[זה יירש\u0006 את \u0005הכל]\u0006 \u0003ולא האי לירות כוליה\u0004 \u0005[זה יירש\u0006 את \u0005הכל],\u0006 \u0003אלא כי הדדי לירתו\u0004 \u0005[זה כמו זה ירשו]\u0006 ויחלקו ביניהם בשווה את הירושה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 אם אתה אומר שזכות הבן והבת שווה בירושה, אם כן, הכתוב \"איש כי ימות ובן אין לו\" (במדבר כז, ח) ממנו למדים שאם יש לו בן — הבן יורש, נראה מיותר, \u0003ואצטריך קרא לאשמועינן, היכא דלית ליה\u0004 \u0005[ו\u0006כי \u0005צריך הפסוק להשמיע לנו\u0006 ש\u0005במקום שאין לו]\u0006 \u0003אלא חד ברא\u0004 \u0005[בן אחד]\u0006 \u0003לירתינהו לכולהו נכסי\u0004 \u0005[ש\u0006הוא \u0005יורש את כל הנכסים]?!\u0006 הציע רב פפא: \u0003ודלמא הא קא משמע לן\u0004 \u0005[ושמא\u0006 דבר \u0005זה השמיע לנו]\u0006 כתוב זה, ש\u0003בת נמי\u0004 \u0005[גם כן]\u0006 \u0003בת ירושה היא!\u0004 ומשיבים: דבר זה אינו נזקק להוכחה בדרך זו, \u0003ההוא\u0004 \u0005[אותו\u0006 ענין\u0005]\u0006 \u0003מ\"וכל בת ירשת נחלה\"\u0004 (במדבר לו, ח) \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005],\u0006 שנאמר במפורש שאף הבת יורשת.","\u0003רב אחא בר יעקב אמר, מהכא\u0004 \u0005[מכאן]\u0006 יש מקור לדין המשנה שהבן יורש לבדו את אביו לפני הבת, ממה שאמרו בנות צלפחד כשתבעו את נחלת אביהן: \u0003\"למה יגרע שם אבינו מתוך משפחתו כי אין לו בן\"\u0004 (במדבר כז, ד), ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום ש\u0003אין לו בן, הא\u0004 \u0005[הרי]\u0006 אם \u0003יש לו בן\u0004 — \u0003בן קודם,\u0004 ולא היו תובעות דבר.","ומקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003בנות צלפחד הוא דקאמרן הכי\u0004 \u0005[שאמרו כך]\u0006 משום שחשבו שכך הדין, וכך היה מקובל, אבל לאחר מכן, כשהיה דבר ה' למשה, \u0003ניתנה תורה ונתחדשה הלכה,\u0004 ויש דין חדש — שהבת יורשת כבן! \u0003אלא, מחוורתא כדשנין מעיקרא\u0004 \u0005[מחוור,\u0006 ברור הדבר \u0005כפי שתירצנו בתחילה],\u0006 כלומר, כפי שהסביר אביי, מן הפסוק \"ובן אין לו והעברתם\" וכו'.","\u0003רבינא אמר, מהכא\u0004 \u0005[מכאן]\u0006 למדים דבר זה, שהבן קודם לבת, שנאמר: \u0003\"הקרב אליו\"\u0004 (במדבר כז, יא), \u0003\"הקרב\"\u0004 — \u0003קרוב קודם,\u0004 והבן קרוב לאב יותר מן הבת.","ותוהים: \u0003ומאי\u0004 \u0005[ומה]\u0006 ה\u0003קורבה\u0004 של \u0003בן\u0004 יותר \u0003מ\u0004של ה\u0003בת\u0004 — \u0003ש\u0004כן ה\u0003בן קם תחת אביו ליעדה\u0004 לשאת אמה עבריה בכסף שקנה אותה אביו, \u0003ו\u0004כן \u0003לשדה אחוזה\u0004 שאם הקדישה האב וגאלה הבן, אינה יוצאת לכהנים ביובל? והרי \u0003יעדה\u0004 אין ממנה ראיה, כי \u0003בת לאו\u0004 \u0005[לא]\u0006 \u0003בת יעדה\u0004 \u0005[ייעוד]\u0006 \u0003היא,\u0004 שהרי אין הבת יכולה לשאת לאשה אותה אמה עבריה, ולכן אין דין זה נחשב כיתרון של הבן על הבת! ו\u0003שדה אחוזה נמי\u0004 \u0005[גם כן]\u0006 — \u0003מהאי פירכא גופה הוא דהא קיימא ליה\u0004 \u0005[מאותה פירכה עצמה שמוחזקת לו]\u0006 \u0003לתנא\u0004 שהבן עומד תחת אביו לענין שדה אחוזה, ולא קרוב אחר — ממנה עצמה יש ללמוד שהבת קרובה לאב כמו הבן. שהרי כך הוא שונה כפירכה: \u0003כלום יש יבום אלא במקום שאין בן,\u0004 ובזה הרי אין יתרון לבן על הבת! \u0003אלא, מחוורתא כדשנין מעיקרא\u0004 \u0005[מחוור כמו שתירצנו מתחילה]\u0006 כדברי אביי, מ\"ובן אין לו והעברתם את נחלתו לבתו\".","\u0003ואי בעית אימא, מהכא\u0004 \u0005[ואם תרצה אמור, מכאן],\u0006 שנאמר בענין ירושה: \u0003\"והתנחלתם אתם לבניכם אחריכם\"\u0004 (ויקרא כה, מו), ונדייק מלשון הכתוב: \u0003\"בניכם\"\u0004 — \u0003ולא בנותיכם.\u0004 ותוהים: \u0003אלא מעתה\u0004 שאתה מדייק כך, מה שנאמר \u0003\"למען ירבו ימיכם וימי בניכם\"\u0004 (דברים יא, כא), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תדייק ותאמר: \u0003\"בניכם\"\u0004 — \u0003ולא בנותיכם?\u0004 וכי אין הבנות ראויות להתברך באריכות ימים?","ומשיבים: \u0003ברכה שאני\u0004 \u0005[שונה],\u0006 שבמקום שנאמרה ברכה, אף שנאמרה בלשון \"בניכם\" אין אומרים שדייק הכתוב להוציא את הבנות, וזה שנאמר \"בניכם\" הכוונה היא לכל הנולדים לכם. אבל במקום שמדובר בפסק הלכה, יש לדייק שהכוונה היא לבנים דווקא.","שנינו במשנה ש\u0003האחין מן האב נוחלין ומנחילין וכו'.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה, שדווקא אחים מן האב? \u0003אמר רבה: אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה מ\u0003\"אחוה\" \"אחוה\" מבני יעקב, מה להלן\u0004 בבני יעקב, האחים שמדובר בהם הריהם אחים \u0003מן האב ולא מן האם\u0004 (\"שנים עשר עבדיך אחים אנחנו בני איש אחד\". בראשית מב, יג), \u0003אף כאן\u0004 לענין ירושה (\"ונתתם את נחלתו לאחיו\". במדבר כז, ט) אחים נחשבים דווקא אלה הבאים \u0003מן האב ולא מן האם.\u0004","ושואלים: \u0003ולמה לי\u0004 ראיה זו מבני יעקב? והלא \u0003\"ממשפחתו וירש אתה\"\u0004 (במדבר כז, יא) \u0003כתיב\u0004 \u0005[נאמר],\u0006 וכבר למדנו שרק \u0003משפחת אב קרויה \"משפחה\", משפחת אם אינה קרויה \"משפחה\",\u0004 ומכאן שבכל דיני הירושה הולכים אחר קרובים מצד האב דווקא!","ומשיבים: \u0003אין הכי נמי\u0004 \u0005[אכן כך\u0006 הוא \u0005גם כן],\u0006 שאין הראיה נחוצה לענין דיני ירושה, \u0003וכי איתמר\u0004 \u0005[וכאשר נאמרו]\u0006 דברי \u0003רבה,\u0004 לא לענין ירושה נאמרו, אלא \u0003לענין יבום איתמר\u0004 \u0005[נאמרו],\u0006 שהאח מייבם את אשת אחיו מן האב ולא מן האם.","שנינו במשנה ש\u0003האיש\u0004 יורש \u0003את אמו וכו'.\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין\u0006 לנו \u0005הדברים הללו]\u0006 שהבן יורש את אימו? ומשיבים, \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006"],["נאמר: \u0003\"וכל בת ירשת נחלה ממטות בני ישראל\"\u0004 (במדבר לו, ח), ויש לשאול: \u0003היאך בת יורשת שני מטות\u0004 (שני שבטים)? \u0003אלא זו\u0004 בת \u0003שאביה משבט אחד ואמה משבט אחר, ומתו\u0004 שניהם, \u0003וירשתן.\u0004 ומכלל הדברים אתה למד שהבת יורשת את אימה.","\u0003ואין לי אלא בת\u0004 שיורשת את אימה, \u0003בן מנין\u0004 שהוא יורש את אימו? \u0003אמרת קל וחומר\u0004 הוא: \u0003ומה בת שהורע כחה בנכסי האב\u0004 שאינה יורשת אותו אלא בזמן שאין בן — מכל מקום \u0003יפה כחה בנכסי האם,\u0004 שלמדנו שהיא יורשת את אימה, \u0003בן שיפה כחו בנכסי האב\u0004 — \u0003אינו דין שיפה כחו בנכסי האם?!\u0004 וממשיכים: \u0003וממקום שבאת\u0004 מאותו מקום ממנו הבאת ראיה זו, יכול אתה להמשיך ולומר: \u0003מה להלן\u0004 בנכסי האב \u0003בן קודם לבת, אף כאן\u0004 בנכסי האם \u0003בן קודם לבת.\u0004","ואילו \u0003ר' יוסי בר' יהודה ור' אלעזר בר' יוסי אמרו משום\u0004 (בשם) \u0003ר' זכריה בן הקצב: אחד הבן ואחד הבת שוין בנכסי האם. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003דיו ל\u0004דבר ה\u0003בא מן הדין,\u0004 כלומר, הנלמד מקל וחומר, \u0003להיות כנדון\u0004 ממנו למדנו דין זה, ולא יותר ממנו. וכיון שלמדנו שבן יורש את אימו בקל וחומר מן הבת, אי אפשר לומר שעל ידי קל וחומר זה נעדיף את הבן על הבת.","ותוהים: \u0003ו\u0004האם ה\u0003תנא קמא לא דריש\u0004 \u0005[הראשון אינו דורש]\u0006 את מידת \u0003\"דיו\"? והא\u0004 \u0005[והרי]\u0006 הגבלה זו של \u0003\"דיו\"\u0004 למידת קל וחומר, \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003הוא!\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בהסבר המידות שהתורה נדרשת בהן: \u0003מדין קל וחומר כיצד?\u0004 שנאמר: \u0003\"ויאמר ה' אל משה ואביה ירק ירק בפניה הלא תכלם שבעת ימים\u0004 תסגר שבעת ימים מחוץ למחנה\u0003\"\u0004 (במדבר יב, יד), כלומר, אם אב יורק בפני בתו ונוזף בה, הריהי צריכה להיות בנידוי שבעה ימים. ולפיכך אף עתה, כשנזף בה הקדוש ברוך הוא, עליה להיות בהסגר שבעה ימים. ויש לשאול: אם באביה שבעה ימים \u0003קל וחומר לשכינה ארבעה עשר\u0004 יום!","\u0003אלא, דיו לבא מן הדין\u0004 (שכינה) \u0003להיות כנדון\u0004 (אביה), ולכן \"תסגר שבעת ימים\"!","ומשיבים: אמנם \u0003בעלמא דריש\u0004 \u0005[בכלל דורש]\u0006 גם התנא קמא הגבלה זו של \u0003\"דיו\", ושאני הכא\u0004 \u0005[ו\u0006אולם \u0005שונה כאן],\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ממטות\",\u0004 ובכך הוא \u0003מקיש\u0004 (משווה) \u0003מטה האם למטה האב, מה מטה האב\u0004 — \u0003בן קודם לבת, אף מטה האם\u0004 — \u0003בן קודם לבת.\u0004","מסופר: \u0003רב ניתאי סבר למעבד עובדא\u0004 \u0005[סבור\u0006 היה \u0005לעשות מעשה]\u0006 לענין ירושת בן ובת בנכסי אימם \u0003כר' זכריה בן הקצב, אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל: כמאן\u0004 \u0005[כמי]?\u0006 — \u0003כזכריה, אפס\u0004 \u0005[בטל]\u0006 \u0003זכריה,\u0004 שדבריו אלה לא נתקבלו בהלכה. ועוד מסופר, \u0003ר' טבלא עבד עובדא\u0004 \u0005[עשה מעשה]\u0006 \u0003כר' זכריה בן הקצב, אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: מאי האי\u0004 \u0005[מה זה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 ש\u0003אמר רב חיננא בר שלמיא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: הלכה כר' זכריה בן הקצב. אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003זיל אהדר\u0004 \u0005[לך חזור]\u0006 \u0003בך\u0004 ובטל את הדין שפסקת, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003מפיקנא\u0004 \u0005[אוציא]\u0006 \u0003לך\u0004 את \u0003רב חיננא בר שלמיא מאוניך\u0004 \u0005[מאוזנך],\u0006 שאענוש אותך עונש קשה על שעשית שלא כדין.","ועוד מסופר: \u0003רב הונא בר חייא סבר למעבד עובדא\u0004 \u0005[סבור\u0006 היה \u0005לעשות מעשה]\u0006 בירושת בן ובת בנכסי אימם \u0003כר' זכריה בן הקצב, אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: מאי האי\u0004 \u0005[מה זה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 ש\u0003אמר רב הונא אמר רב: הלכה כר' זכריה בן הקצב. אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: האם \u0003אשלח ליה\u0004 \u0005[לו]\u0006 לרב הונא לשאול אותו אם כך אמר? \u0003איכסיף\u0004 \u0005[התבייש]\u0006 רב הונא בר חייא, משום שלא היה בטוח שאמר רב הונא את הדברים הללו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003השתא כי נח נפשיה\u0004 \u0005[עכשיו אם היה נפטר]\u0006 \u0003רב הונא, איתריסת לקבלי\u0004 \u0005[היית מעיז כנגדי]\u0006 ואומר לי שכך אמר רב הונא. אלא רק משום שהוא חי אינך יכול להעיז פנים בכך.","ושואלים: \u0003ואיהו כמאן סברה\u0004 \u0005[והוא,\u0006 רב נחמן, \u0005כמי הוא סבר\u0006 במה שאמר\u0005]?\u0006 שהרי לכאורה היו חכמים שונים שפסקו בשם רב כר' זכריה בן הקצב! ומשיבים: \u0003כי הא\u0004 \u0005[כמו\u0006 הלכה \u0005זו]\u0006 של \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003אין הלכה כר' זכריה בן הקצב.\u0004","מסופר: \u0003מיסתמיך ואזיל\u0004 \u0005[היה נסמך והולך]\u0006 \u0003ר' ינאי,\u0004 שכבר הזדקן וכהו עיניו מראות, \u0003אכתפא\u0004 \u0005[על כתפו]\u0006 של \u0003ר' שמלאי שמעיה\u0004 \u0005[שמשו],\u0006 \u0003ואתי\u0004 \u0005[ובא]\u0006 \u0003ר' יהודה נשיאה לאפייהו\u0004 \u0005[הנשיא לפניהם,\u0006 כנגדם\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' שמלאי לר' ינאי: \u0003בר אינש דאתא לקיבלנא\u0004 \u0005[בן האדם שבא כנגדנו],\u0006 \u0003הוא יאי\u0004 \u0005[נאה]\u0006 \u0003וגולתיה יאי\u0004 \u0005[וטליתו נאה].\u0006 \u0003כי מטא לגביה גששה\u0004 \u0005[כאשר הגיע\u0006 ר' יהודה הנשיא \u0005אצלו מישש\u0006 ר' ינאי את הטלית\u0005],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לר' שמלאי שמשו: \u0003דין שיעוריה\u0004 \u0005[\u0006אריג \u0005זה שיעורו\u0006 לענין קבלת טומאה\u0005]\u0006 \u0003כשק,\u0004 כלומר, אין זו גלימה משובחת, לפי שהיא עבה וקשה.","כיון שפגש אותו \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 ר' יהודה נשיאה מר' ינאי: \u0003מנין לבן שקודם לבת בנכסי האם? אמר ליה\u0004 \u0005[לו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מטות\", מקיש\u0004 משווה הכתוב \u0003מטה האם למטה האב, מה מטה האב\u0004 — \u0003בן קודם לבת, אף מטה האם\u0004 — \u0003בן קודם לבת. אמר ליה\u0004 \u0005[לו]\u0006 ר' יהודה נשיאה: \u0003אי\u0004 \u0005[אם\u0006 כן\u0005],\u0006 נאמר גם: \u0003מה\u0004 בירושת \u0003מטה האב\u0004 — \u0003בכור נוטל פי שנים, אף\u0004 בירושה מ\u0003מטה האם\u0004 כשהוא יורש את אמו יהיה \u0003בכור נוטל פי שנים,\u0004 אם הכתוב משווה את הדינים לגמרי!"],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' ינאי \u0003לשמעיה\u0004 \u0005[לשמשו]\u0006 ר' שמלאי: \u0003גוד\u0004 \u0005[משוך]\u0006 הובל אותי מכאן, \u0003לית דין צבי למילף\u0004 \u0005[אין\u0006 אדם \u0005זה רוצה ללמוד]\u0006 אלא להקשות קושיות בלתי חשובות. ושואלים: \u0003וטעמא מאי\u0004 \u0005[ומהו הטעם],\u0006 מהו התירוץ של הקושי הזה? \u0003אמר אביי, אמר קרא\u0004 \u0005[הכתוב]\u0006 בדין ירושת הבכור: \u0003\"\u0004כי את הבכור. . . יכיר לתת לו פי שנים \u0003בכל אשר ימצא לו\"\u0004 (דברים כא, יז), ומכאן נדייק: \u0003\"לו\"\u0004 — \u0003ולא לה.\u0004","ומקשים, \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא ב\u0003בחור\u0004 שאין לו ילדים, \u0003שנשא אלמנה\u0004 שיש לה ילדים מאדם אחר, שאז הבן הנולד להם הוא בכורו, אבל אינו הבכור שלה, \u0003אבל בחור שנשא בתולה הכי נמי דשקיל\u0004 \u0005[כך גם כן\u0006 יהא הדין \u0005שיטול\u0006 פי שניים\u0005]\u0006 בנכסי האם!","\u0003אמר רב נחמן בר יצחק, אמר קרא\u0004 \u0005[הכתוב]\u0006 בהמשך אותו פסוק: \u0003\"\u0004כי הוא \u0003ראשית אנו\",\u0004 ומכאן יש לדייק: \u0003\"אונו\"\u0004 — \u0003ולא אונה.\u0004","ומקשים: \u0003ההוא מבעיא ליה\u0004 \u0005[אותו\u0006 כתוב \u0005נצרך לו]\u0006 ללמוד ממנו דבר אחר: \u0003ל\u0004ילד ש\u0003בא\u0004 (נולד) \u0003אחר\u0004 שנולדו לאמו \u0003נפלים\u0004 (עוברים בני פחות מתשעה חדשים שנולדו מתים), \u0003דלהוי\u0004 \u0005[שיהיה]\u0006 \u0003בכור ל\u0004ענין \u0003נחלה,\u0004 אף שאינו בכור לענין פדיון הבן. וכיצד לומדים דבר זה? שמבינים \"אונו\" — מלשון \"אנינות\", שבן בכור לענין נחלה נקרא רק \u0003מי שלבו\u0004 של אביו \u0003דווה\u0004 (כואב, חולה) \u0003עליו\u0004 כשמת, שהוא ילד שיש בו חיים, \u0003יצא זה\u0004 הנפל \u0003שאין לבו\u0004 של אביו \u0003דווה עליו\u0004 כשמת, ולכן הבא אחריו נחשב בכור!","ומשיבים: \u0003אם כן,\u0004 אם רק לצורך זה באה מילה זו, \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003\"כי הוא ראשית און\", מאי\u0004 \u0005[מה\u0006 פשר\u0005]\u0006 ההדגשה \u0003\"אונו\",\u0004 ממנה משמע דווקא אונו שלו? \u0003שמע מינה תרתי\u0004 \u0005[למד ממנה שני\u0006 דברים\u0005],\u0006 הן לענין אנינות, והן לענין בכורה בירושת האב דווקא.","ומקשים, \u0003ואכתי אימא\u0004 \u0005[ועדיין אמור\u0006 כך\u0005]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא ב\u0003אלמון\u0004 (אלמן) \u0003שנשא בתולה,\u0004 שיש לו כבר בן שהוא ראשית אונו, ובן זה שנולד לאשתו השניה אינו ראשית אונו, ובמקרה זה אינו נוטל פי שנים בנכסי האם, \u0003אבל בחור שנשא בתולה הכי נמי דשקיל\u0004 \u0005[כך גם כן שנוטל]\u0006 הבן הבכור פי שנים גם בנכסי אמו!","\u0003אלא אמר רבא:\u0004 לא מ\"אונו\" יש לדייק, אלא \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לו משפט הבכרה\"\u0004 (דברים כא, יז), לומר: \u0003משפט הבכורה\u0004 נוהג דווקא \u0003ל\u0004ענין ירושת \u0003איש, ולא משפט הבכורה\u0004 \u0003ל\u0004ענין ירושת \u0003אשה.\u0004","שנינו במשנה ש\u0003האיש\u0004 יורש \u0003את אשתו.\u0004 ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 ומשיבים, \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר בדין ירושה \"ואם אין אחים לאביו ונתתם את נחלתו לשארו הקרוב אליו ממשפחתו וירש אותה\" (במדבר כז, יא), ואמרו חכמים: \u0003\"שארו\"\u0004 — \u0003זו אשתו, מלמד שהבעל יורש את אשתו\u0004 כפי שיבואר להלן. \u0003יכול אף היא תירשנו? תלמוד לומר: \"וירש אתה\",\u0004 לומר: \u0003הוא יורש אותה, ואין היא יורשת אותו.\u0004","ומקשים: \u0003והא קראי לאו הכי כתיבי\u0004 \u0005[והרי הכתובים לא כך נאמרו]\u0006 שהרי במקרא כתוב \"ונתתם את נחלתו לשארו הקרוב אליו ממשפחתו וירש אותה\", ואם \"שארו\" היא אשתו, הרי משמעות הכתובים הפוכה — שהאשה יורשת את בעלה! \u0003אמר אביי, תריץ הכי\u0004 \u0005[תירץ,\u0006 ישב \u0005כך]\u0006 כאילו היה הפסוק כתוב כך: \u0003ונתתם את נחלתו לקרוב אליו.\u0004 שהוא דין כללי בירושת הקרובים. ודין שני: \u0003שארו\u0004 — \u0003וירש אותה,\u0004 שהבעל יורש את שארו, היא אשתו.","\u0003אמר רבא: סכינא חריפא מפסקא קראי\u0004 \u0005[סכין חדה פוסקת,\u0006 קוטעת \u0005מקראות]?\u0006 כיצד אתה יכול לחתוך את הפסוק בצורה זו, לשנות בו את סדר המילים ולחתוך מהן אותיות! \u0003אלא אמר רבא, הכי קאמר\u0004 \u0005[כך אמר]\u0006 כך יש להבין את הכתוב: \u0003ונתתם את נחלת שארו לו,\u0004 שמצרפים את אותיות \"נחלתו לשארו\" בדרך אחרת: נוטלים את האות וא\"ו מ\"נחלתו\" ואת האות למ\"ד מ\"לשארו\", ומצרפים אותן למלה נוספת: \"לו\". ומסבירים, \u0003קא סבר\u0004 \u0005[סבור הוא]\u0006 שיש לדרוש את הכתובים בדרך של \u0003גורעין\u0004 אות ממלה אחת \u0003ומוסיפין\u0004 אותה למלה אחרת, \u0003ודורשין\u0004 ולמדים מהצירוף הלשוני שהתקבל. עד כאן בביאור שיטת הברייתא שהובאה לעיל.","ומעירים: \u0003והאי תנא מייתי לה מהכא\u0004 \u0005[ותנא זה מביא אותה\u0006 הלכה, שהבעל יורש את אשתו, \u0005מכאן],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"וירש אתה\"\u0004 (במדבר כז, יא), \u0003מלמד שהבעל יורש את אשתו,\u0004 אלו \u0003דברי\u0004 \u0003ר' עקיבא\u0004 מעין דרשה זו שנדרשה בברייתא לעיל;","\u0003ר' ישמעאל אומר: אינו צריך\u0004 לדרשה זו, ש\u0003הרי הוא אומר: \"וכל בת ירשת נחלה ממטות בני ישראל לאחד ממשפחת\u0004 מטה אביה תהיה לאשה למען יירשו בני ישראל איש נחלת אבותיו\u0003\"\u0004 (במדבר לו, ח), \u0003בהסבת\u0004 נחלה משבט לשבט על ידי \u0003הבעל הכתוב מדבר,\u0004 כלומר בציווי זה, שבת היורשת נחלה (שאין לה אחים) חייבת להינשא דווקא לבן שבטה, בא הכתוב למנוע שנחלת שבט אחד תיסוב לשבט אחר, הואיל ולאחר מותה הבעל יורש אותה.","\u0003ואומר: \"ולא תסב נחלה לבני ישראל ממטה אל מטה\"\u0004 (במדבר לו, ז), \u0003ואומר: \"ולא תסב נחלה ממטה למטה אחר\"\u0004 (במדבר לו, ט);","\u0003ואומר: \"ואלעזר בן אהרן מת ויקברו אתו בגבעת פנחס בנו\u0004 אשר ניתן לו בהר אפרים\u0003\"\u0004 (יהושע כד, לג), ויש לשאול: \u0003וכי מנין\u0004 יש \u0003לפנחס\u0004 קרקע \u0003שלא היה לו לאלעזר\u0004 אביו? \u0003אלא, מלמד שנשא פנחס אשה\u0004 בעלת נחלה \u0003ומתה וירשה,\u0004 וכך היתה לו נחלה משל עצמו. ומכאן ראיה שהבעל יורש את אשתו.","\u0003ואומר: \"ושגוב הוליד את יאיר ויהי לו עשרים ושלש ערים\u0004 \u0003בארץ הגלעד\"\u0004 (דברי הימים א ב, כב),"],["\u0003וכי מנין\u0004 היתה \u0003ליאיר\u0004 נחלה \u0003שלא היה לו לשגוב\u0004 אביו? אלא \u0003מלמד שנשא יאיר אשה\u0004 בעלת נחלה \u0003ומתה וירשה.\u0004","ומעתה באים להסביר את הברייתא הזו: \u0003מאי\u0004 \u0005[מה\u0006 ענין\u0005]\u0006 \u0003\"ואומר\"?\u0004 מדוע צריך להביא ראיות נוספות ואינו מסתפק בראיה הראשונה? ומסבירים, שכל ראיה נוספת הובאה כדי להשיב לטענה שאפשר היה לדחות בה את הראיה הקודמת. וכך יש להבין: \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שהכתוב \"וכל בת יורשת נחלה... לאחד ממשפחת מטה אביה תהיה לאשה למען יירשו בני ישראל איש נחלת אבותיו\" \u0003בסבת\u0004 (בהסבת) נחלה על ידי \u0003הבן קא קפיד קרא\u0004 \u0005[מקפיד הכתוב]\u0006 שבנה, המתייחס לשבט אביו, יורשה, ובגללו עלולה הנחלה לעבור לשבט אחר, \u0003אבל בעל לא ירית\u0004 \u0005[יורש],\u0006 על כן \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 פסוק נוסף, מיותר לכאורה, שנאמר: \u0003\"ולא תסב נחלה לבני ישראל ממטה למטה\"\u0004 (במדבר לו, ז) והוא מדבר בהסבת הבעל.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שהכתוב עדיין מדבר רק בהסבת נחלה על ידי הבן ולא הבעל, ואילו הכתוב הנוסף הזה לא בא אלא כדי \u0003לעבור עליו בלאו ועשה,\u0004 לומר שלא זו בלבד שיש מצות עשה בדבר, אלא שיש בו גם איסור לא תעשה של \"לא תסוב נחלה\" — \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פסוק נוסף שבו נאמר בענין זה איסור לא תעשה: \u0003\"\u0004ו\u0003לא תסב נחלה ממטה למטה אחר\"\u0004 (במדבר לו, ט).","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שגם הפסוק הזה מדבר בהסבה על ידי הבן, ובא הכתוב להוסיף עליו איסור נוסף של \"לא תעשה\", \u0003לעבור עליו בשני לאוין ועשה\u0004 — \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לירושת הבעל, ממה שנאמר: \u0003\"ואלעזר בן אהרן מת\u0004 ויקברו אותו בגבעת פנחס בנו","\u0003\"\u0004(יהושע כד, לג), וכי מנין היה לפנחס שלא מאלעזר? אלא מלמד שנשא אשה וירשה. \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שלא ירש פנחס נחלה זו מאשתו, אלא מאימו, ש\u0003אלעזר הוא דנסיב איתתא\u0004 \u0005[שנשא אישה]\u0006 בעלת נחלה \u0003ומתה, וירתה\u0004 \u0005[וירש אותה]\u0006 \u0003פנחס\u0004 בנה, ואם כן, יש פה ירושת הבן ולא ירושת הבעל, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה שנאמר: \u0003\"ושגוב הוליד את יאיר\u0004 ויהי לו עשרים ושלוש ערים בארץ הגלעד","\u0003\"\u0004(דברי הימים א ב, כב), וכי מנין ליאיר שלא היה לשגוב? אלא ודאי מאשתו ירש. \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003התם נמי הכי\u0004 \u0005[שם גם כן כך]\u0006 \u0003הוא\u0004 שיאיר ירש את אימו המתה, \u0003אם כן, תרי קראי\u0004 \u0005[שני פסוקים]\u0006 ללמד אותו דבר \u0003למה לי?\u0004 עד כאן בהסבר דברי הברייתא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: ממאי\u0004 \u0005[ממה]\u0006 מנין שכך הוא? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כך: ה\u0003בעל לא ירית\u0004 \u0005[יורש],\u0006 \u0003וקראי\u0004 \u0005[והפסוקים]\u0006 עוסקים \u0003בסבת\u0004 (בהסבת) נחלה על ידי \u0003הבן כדשנינן\u0004 \u0005[כפי שתירצנו\u0006 והסברנו\u0005]\u0006 לעבור על ענין זה בשני לאוין ועשה, \u0003ויאיר\u0004 שהיתה לו נחלה שלא היתה לאביו, מדובר \u0003דזבין מיזבן\u0004 \u0005[שקנה אותה]\u0006 מאדם אחר, \u0003ו\u0004כן \u0003פנחס נמי דזבין מיזבן\u0004 \u0005[גם כן,\u0006 מדובר \u0005שקנה אותה]\u0006 מאדם אחר, ולא שירש אותה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003פנחס דזבין מיזבן לא מצית אמרת\u0004 \u0005[שקנה\u0006 נחלה זו שבה קבור אביו — \u0005אין אתה יכול לומר],\u0006 ומדוע? ש\u0003אם כן,\u0004 שהיתה זו קניה, \u0003נמצאת שדה חוזרת ביובל\u0004 לבעליה הראשונים, \u0003ונמצא צדיק\u0004 זה, אלעזר, \u0003קבור בקבר שאינו שלו.\u0004","וחזר רב פפא והקשה: \u0003אלא אימא\u0004 \u0005[אמור]\u0006 אפשר לומר באופן אחר, ש\u0003נפלה ליה\u0004 \u0005[לו]\u0006 לפנחס נחלה זו \u0003משדה חרמים,\u0004 בתור כהן. שאם נותן אדם קרקע חרם לה', הריהי נעשית נחלת עולם לכהנים, ואם כן, אין ראיה מכאן. ועדיין נאמר כי הכתוב המחייב בת יורשת נחלה להינשא לבן שבט אביה, חושש להסבת הנחלה בסיבת הבן דווקא!","\u0003אמר אביי:\u0004 מכל מקום, אין הנישואין לאיש משבט אביה של האשה מונעים העברת נחלה משבט לשבט, שהרי כתוב זה עוסק באשה שאימה משבט אחר (ראה לעיל בבא בתרא קיא, א), וגם אם תינשא לאיש משבט אביה, \u0003סוף סוף הא קא מתעקרא\u0004 \u0005[הרי נעקרת]\u0006 \u0003נחלה משבטא דאימא לשבטא דאבא\u0004 \u0005[משבט האם לשבט האב],\u0006 שהרי בנה קרוי על שם אביו!","ודחה רב פפא: \u0003וממאי\u0004 \u0005[וממה]\u0006 מוכיח אתה כן לענייננו? \u0003דלמא שאני התם\u0004 \u0005[שמא שונה שם],\u0006 \u0003שכבר הוסבה\u0004 הנחלה על ידי אימה של אשה זו, כשנישאה לאב, ועל כך לא הקפידה התורה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003שכבר הוסבה לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 שהרי מכל מקום נמצא שמוסבת נחלה משבט לשבט.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יימר לרב אשי:\u0004 מכל מקום, אף לדברי אביי קשה הדבר, שכן \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שאין איסור הסבת נחלה במקרה \u0003שכבר הוסבה, היינו דמתוקמא קרא\u0004 \u0005[זה שמועמד,\u0006 מוסבר \u0005הכתוב]\u0006 \u0003בין בסבת הבן בין בסבת הבעל,\u0004 שנישואי האשה לאיש משבט אביה מועילים לכך.","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003שכבר הוסבה,\u0004 אם כן, \u0003כי מינסבא\u0004 \u0005[כאשר\u0006 היא \u0005נישאת\u0006 אפילו\u0005]\u0006 \u0003לאחד ממשפחת מטה אביה, מאי הוה\u0004 \u0005[מה יהיה]?\u0006 מה התיקון בזה? \u0003הא מתעקרא\u0004 \u0005[הרי\u0006 בכל זאת \u0005נעקרת]\u0006 \u0003נחלה משבטא דאימא לשבטא דאבא\u0004 \u0005[משבט האם לשבט האב]!\u0006","אמר לו רב אשי: יש תקנה לדבר, \u0003דמנסבינן לה לגברא דאבוהי משבטא דאבוה ואימיה משבטא דאימה\u0004 \u0005[שמשיאים אותה לאיש שאביו\u0006 הוא \u0005משבט של אביה ואמו משבט של אימה],\u0006 ונמצא שהנחלה נשארת בדיוק באותו מצב שבו היתה בידי האשה."],["ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שצריך להשיא בת יורשת נחלות לאיש שאביו ממטה אביה ואמו ממטה אימה, \u0003האי\u0004 \u0005[זה]\u0006 הכתוב \"לאחד ממשפחת מטה אביה תהיה לאשה\" (במדבר לו, ח) — \u0003\"לאחד ממשפחת מטה אביה ואמה\u0004 תהיה לאשה \u0003\"\u0004\u0003מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 ומשיבים: \u0003אי כתיב הכי\u0004 \u0005[אם\u0006 היה \u0005כתוב כך],\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי הוא הדין \u0003אפילו איפכא\u0004 \u0005[להיפך],\u0006 שתינשא למי שאמו ממטה אביה ואביו ממטה אימה. שאין זה משנה לאיזה שבט שייך הבעל, ובלבד שיהא קשור לשני המטות, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הכתוב באופן זה שצריך הדבר להיות דווקא בצורה זו — שתינשא לאיש שאביו ממטה אביה.","ומעירים: בענין זה של נישואי אשה יורשת נחלה, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 הדנה בהסבת נחלה משבט לשבט \u0003בסבת\u0004 (הסבת) \u0003הבן, ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 הדנה \u0003בסבת הבעל.\u0004 ומפרטים: \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003בסבת הבן:\u0004 מה שנאמר \u0003\"ולא תסב נחלה לבני ישראל ממטה אל מטה\"\u0004 (במדבר לו, ז), \u0003בסבת הבן הכתוב מדבר,\u0004 כלומר, לכן מצוה התורה לאשה להינשא לאיש משבט אביה, כי מאחר שהבן יורש את אימו, הריהו מעביר בכך את הנחלה לשבט אביו.","\u0003אתה אומר: בסבת הבן, או אינו אלא בסבת הבעל? כשהוא אומר: \"ולא תסב נחלה ממטה למטה אחר\"\u0004 (במדבר לו, ט), \u0003הרי בסבת\u0004 נחלה על ידי \u0003הבעל אמור\u0004 הכתוב, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים \"ולא תסב נחלה לבני ישראל ממטה אל מטה\"\u0004 — \u0003בסבת הבן הכתוב מדבר.\u0004"],["\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 מה שנאמר \u0003\"ולא תסב נחלה ממטה למטה אחר\"\u0004 (במדבר לו, ט), \u0003בסיבת\u0004 (בהסבת) נחלה משבט לשבט אחר על ידי \u0003הבעל הכתוב מדבר;\u0004","\u0003אתה אומר בסיבת הבעל, או אינו אלא בסיבת הבן? כשהוא אומר: \"ולא תסב נחלה לבני ישראל ממטה אל מטה\"\u0004 (במדבר לו, ז) — \u0003הרי הסיבת הבן אמור, הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים \"ולא תסב נחלה ממטה למטה אחר\"?\u0004 — \u0003בסיבת הבעל הכתוב מדבר.\u0004","ומעירים: \u0003דכולי עלמא מיהת\u0004 \u0005[לדעת הכל,\u0006 לפי שתי הברייתות, \u0005על כל פנים]\u0006 \u0003\"ממטה למטה אחר\"\u0004 — \u0003בסיבת הבעל הכתוב מדבר,\u0004 שדבר זה פשוט לדורש. ושואלים: \u0003מאי משמע\u0004 \u0005[מה,\u0006 כיצד \u0005נשמע]\u0006 דבר זה מן הכתוב? — \u0003סימן\u0004 לדבר \u0003אמר רבה בר רב שילא:\u0004 \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בפסוק זה \u0003\"איש\",\u0004 ואם כן כוונתו לבעל (כמו \"אלימלך איש נעמי\", ברות א, ג, שהכוונה היא בעלה של נעמי). ותוהים על כך: הלא \u0003תרוייהו\u0004 \u0005[שניהם]\u0006 בשני הפסוקים, \u0003\"איש\" כתיב בהו\u0004 \u0005[כתוב בהם]\u0006 ואם כן יש להעמיד את שניהם בהסבת הבעל!","\u0003אלא\u0004 יש לדחות פירוש זה ולומר באופן אחר, \u0003אמר רב נחמן בר יצחק, אמר קרא\u0004 \u0005[הכתוב]\u0006 בהמשך הפסוק: \"כי איש בנחלתו \u0003ידבקו\u0004 בני ישראל\", ולשון \"דביקה\" שייכת בנישואין (כמו \"ודבק באשתו\". בראשית ב, כד). ומקשים: והלא \u0003תרוייהו\u0004 \u0005[שניהם],\u0006 בשני הפסוקים \u0003\"ידבקו\" כתיב בהו\u0004 \u0005[כתוב בהם]!\u0006","\u0003אלא\u0004 יש לדחות הסבר זה ולומר באופן אחר, \u0003אמר רבא, אמר קרא\u0004 \u0005[הכתוב]\u0006 באותו פסוק: \u0003\"ידבקו מטות\",\u0004 ודביקה של שני מטות זה בזה היא על ידי נישואין. \u0003רב אשי אמר,\u0004 ראיה אחרת יש בכך, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ממטה למטה אחר\",\u0004 והעברה למטה אחר נעשית על ידי נישואין לבעל, אבל \u0003בן לאו אחר הוא,\u0004 אלא הוא כחלק מאמו.","\u0003אמר\u0004 \u0003ר' אבהו אמר\u0004 \u0003ר' יוחנן אמר\u0004 \u0003ר' ינאי אמר רבי, ומטו\u0004 \u0005[ו\u0006היו \u0005מגיעים,\u0006 מביאים\u0005]\u0006 \u0003בה\u0004 בדברי שמועה זו \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יהושע בן קרחה: מנין לבעל\u0004 היורש את אשתו, \u0003שאינו נוטל\u0004 (יורש) \u0003ב\u0004נכס ה\u0003ראוי\u0004 להגיע לה בירושתה (וכגון שמתו מורישיה אחרי שהיא מתה) \u0003כ\u0004שם שהוא יורש \u0003במוחזק\u0004 בידי אשתו. אלא את הנכסים הראויים יירשו קרוביה (בנה, או קרובים אחרים של אביה)? — \u0003שנאמר: \"ושגוב הוליד את יאיר ויהי לו עשרים ושלוש ערים בארץ הגלעד\"\u0004 (דברי הימים א ב, כב), ויש לשאול: \u0003מנין\u0004 היתה \u0003ליאיר\u0004 נחלה \u0003שלא היה לו לשגוב\u0004 אביו? \u0003אלא, מלמד שנשא שגוב אשה ומתה בחיי מורישיה, ו\u0004אחר כך \u0003מתו מורישיה, וירשה יאיר\u0004 בנה (ולא שגוב בעלה) ומכאן היתה לו נחלה זו.","\u0003ו\u0004כן הכתוב \u0003אומר\u0004 במקום אחר: \u0003\"ואלעזר בן אהרן מת ויקברו\u0004 אותו בגבעת פנחס בנו\u0003\"\u0004 (יהושע כד, לג), \u0003מנין לפנחס\u0004 נחלה \u0003שלא היה לו לאלעזר\u0004 אביו? \u0003מלמד\u0004 הכתוב \u0003שנשא אלעזר אשה ומתה בחיי מורישיה, ומתו\u0004 לאחר מכן \u0003מורישיה, וירשה פנחס.\u0004","ושואלים: \u0003ומאי\u0004 \u0005[ומה]\u0006 הלשון \u0003\"ואומר\"?\u0004 מדוע צריך להביא ראיה דומה נוספת מפנחס בן אלעזר? ומשיבים, שיש להבין כאילו נשאלה שאלה זו: \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003יאיר\u0004 שהיו לו ערים אלו — משום \u0003דהוה נסיב איתתא\u0004 \u0005[שנשא אשה]\u0006 \u0003ומתה וירתה\u0004 \u0005[וירש אותה]\u0006 — \u0003תלמוד לומר: \"ואלעזר בן אהרן מת\u0004 ויקברו אותו בגבעת פנחס בנו \u0003\",\u0004 שירש פנחס את נחלת מורישי אמו, ולא אלעזר. \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003נפלה ליה\u0004 \u0005[לו]\u0006 לפנחס נחלה זו \u0003בשדה חרמים\u0004 שאדם החרים מנחלתו לה', וזכה בה פנחס הכהן, ולא נחלת אמו היא, לכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"בנו\",\u0004 לומר, היתה זו \u0003נחלה הראויה לו\u0004 לאלעזר (אם היתה אשתו מתה לאחר מורישיה), \u0003וירשה בנו.\u0004","שנינו במשנה ש\u0003בני אחות\u0004 יורשים את אחי אימם ואינם מורישים לו. \u0003תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005]:\u0006 \u0003בני אחות, ולא בנות אחות.\u0004"],["ושואלים: \u0003למאי הלכתא\u0004 \u0005[למה\u0006 לאיזו \u0005הלכה]\u0006 נאמרו הדברים הללו? שהרי לעיקר הזכות בירושת אחי אימן — בוודאי גם הבנות יורשות, שכיון שהאם יורשת את אחיה, הרי בתה יורשת אותה! \u0003אמר רב ששת: לקדם,\u0004 לומר שבמקום שיש בנים, הם היורשים את אחי האם ולא הבנות.","ובענין זה \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב שמואל בר רב יצחק קמיה\u0004 \u0005[לפני]\u0006 \u0003רב הונא\u0004 ברייתא: נאמר בסוף פרשת הנחלות \"ונתתם את נחלתו לשארו הקרוב אליו ממשפחתו \u0003וירש\u0004 אותה\" (במדבר כז, יא) — \u0003מקיש\u0004 (משווה) הכתוב \u0003ירושה שניה לירושה ראשונה, מה\u0004 ב\u0003ירושה ראשונה,\u0004 כלומר, ירושת ילדים את אביהם — \u0003בן קודם לבת, אף\u0004 ב\u0003ירושה שניה\u0004 ממורישים אחרים — תמיד \u0003בן קודם לבת.\u0004","מסופר, \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רבה בר חנינא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן\u0004 ברייתא זו: נאמר בענין ירושה \u0003\"והיה ביום הנחילו את בניו\"\u0004 (דברים כא, טז), ותוספת לשון זו של \"ביום\" בענין זה באה ללמד: דווקא \u0003ביום אתה מפיל\u0004 (מנחיל) \u0003נחלות, ואי\u0004 \u0005[ואין]\u0006 \u0003אתה מפיל נחלות בלילה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה,\u0004 לפי דקדוק זה, \u0003דשכיב ביממא\u0004 \u0005[\u0006מי \u0005שמת ביום]\u0006 \u0003הוא\u0004 זה \u0003דירתי ליה בניה\u0004 \u0005[שיורשים אותו בניו],\u0006 ואילו \u0003מאן דשכיב בליליא\u0004 \u0005[מי שמת בלילה]\u0006 \u0003לא ירתי ליה בניה\u0004 \u0005[יורשים אותו בניו]?\u0006","\u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003דין נחלות קא אמרת\u0004 \u0005[אמרת],\u0006 שבית הדין דן בענין זה דווקא ביום ולא בלילה! וראיה לדבר, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מן הכתוב המסיים את פרשת דיני הנחלות, \u0003\"והיתה לבני ישראל לחקת משפט\"\u0004 (במדבר כז, יא), לומדים כי \u0003אורעה\u0004 (זומנה, צורפה) \u0003כל הפרשה כולה להיות\u0004 נחשבת \u0003דין,\u0004 שצריך הרכב של בית דין לדון ולפסוק בו, וחלים בענין זה ההלכות הנוגעות לסדר הדין.","\u0003וכ\u0004דברי \u0003רב יהודה,\u0004 ש\u0003אמר רב יהודה: שלשה שנכנסו לבקר את החולה\u0004 והחולה רוצה לצוות מה ייעשה בנכסיו לאחר מותו, אם \u0003רצו\u0004 — \u0003כותבין\u0004 את דברי הצוואה שלו וחותמים עליה כעדים, ואם \u0003רצו\u0004 — \u0003עושין דין\u0004 שהם יכולים לנהוג בזה כבית דין, שהרי שלושה הם, ולקבוע דברים בתוקף משפט ודין, ולהעביר את הנכסים ליורשים מכוח הוראתם כבית דין. אבל אם באו לבקר את החולה \u0003שנים\u0004 בלבד — \u0003כותבין\u0004 כעדים \u0003ואין עושין דין,\u0004 שהרי רק שלושה יכולים לדון. \u0003ואמר רב חסדא: לא שנו\u0004 הלכה זו \u0003אלא\u0004 כשבאו השלושה לבקרו \u0003ביום,\u0004"],["\u0003אבל בלילה, אפילו שלשה\u0004 — \u0003כותבין\u0004 בלבד \u0003ואין עושין דין, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003דהוו להו\u0004 \u0005[שהרי הם]\u0006 \u0003עדים\u0004 בלבד, כיון שאינם יכולים לדון באותה שעה, לפי שאין דנים בלילה. \u0003ו\u0004גם לאחר מכן אינם יכולים לדון בענין זה, לפי ש\u0003אין עד נעשה\u0004 באותו דבר \u0003דיין. אמר ליה\u0004 \u0005[לו]\u0006 רבה בר חנינא לאביי: \u0003אין\u0004 \u0005[כן],\u0006 \u0003הכי נמי קאמינא\u0004 \u0005[כך גם כן אמרתי],\u0006 כלומר, זו היתה כוונת דברי במה שאמרתי בדברי הברייתא \"אי אתה מפיל נחלות בלילה\" — שאין דנים בדיני נחלות אלא ביום דווקא.","מתוך שהוזכרו דברי רב יהודה בענין שלושה שנכנסו לבקר את החולה, \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה הקשורה לדברים הללו, בדבר שעושים בו \u0003קנין\u0004 סודר כדי לחזק על ידי כך הבטחה או הסכם, \u0003עד אימתי\u0004 יכול המקנה שיהא \u0003חוזר\u0004 בו ממה שעשה עליו קנין? \u0003רבה אמר: כל זמן שיושבין\u0004 באותו מקום יכול לחזור בו. \u0003רב יוסף אמר: כל זמן שעוסקין באותו ענין.\u0004 ואם עברו לעסוק בדברים אחרים, אף שעדיין יושבים הם באותו מקום — שוב אינו יכול לחזור בו.","\u0003אמר רב יוסף: כוותי דידי מסתברא\u0004 \u0005[כשיטתי שלי מסתבר],\u0006 ש\u0003אמר רב יהודה: שלשה שנכנסו לבקר את החולה\u0004 — \u0003רצו כותבין, רצו עושין דין; ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר שיכול לחזור בו \u0003כל זמן שיושבין, ליחוש דלמא הדר ביה\u0004 \u0005[שנחשוש שמא יחזור בו],\u0006 וכיצד עושים דין בדבר שעדיין לא נגמר כלל, שיכול המצווה לשנותו בכל רגע!","\u0003אמר רב אשי: אמריתה לשמעתא קמיה\u0004 \u0005[אמרתי את ההלכה\u0006 הזו \u0005לפני]\u0006 \u0003רב כהנא,\u0004 ושאלתי כך: \u0003ול\u0004שיטת \u0003רב יוסף\u0004 עצמו \u0003מי ניחא\u0004 \u0005[האם נוח\u0006 הדבר\u0005]?\u0006 \u0003וליחוש דלמא הדר ביה\u0004 \u0005[ונחשוש שמא חוזר בו]\u0006 המצווה בעודם עוסקים באותו ענין! \u0003אלא מאי אית\u0004 \u0005[מה יש]\u0006 \u0003לך למימר\u0004 \u0005[לומר]?\u0006 מדוע לשיטת רב יוסף אין חוששים? — שכן מדובר באופן \u0003דיסליקו\u0004 \u0005[ש\u0006כבר \u0005הסתלקו,\u0006 יצאו\u0005]\u0006"],["\u0003מענינא לענינא\u0004 \u0005[מענין לענין],\u0006 ואז אין יכול לחזור בו לשיטתו, אם כן \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 לשיטת רבה, אפשר להסביר ש\u0003קמו והדר יתיבו\u0004 \u0005[ו\u0006אחר כך \u0005חזרו וישבו]\u0006 ואז אינו יכול לחזור בו. ומסכמים: \u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003רב יוסף\u0004 במחלוקותיו עם רבה בשלושת הנושאים הבאים: \u0003בשדה\u0004 (בחלוקת שדה בין אחים, לעיל בבא בתרא יב,ב), \u0003ענין\u0004 האמור כאן, שקנין חוזר כל זמן שעסוקים באותו ענין, \u0003ו\u0004בדין \u0003מחצה\u0004 (כמבואר להלן בדף קמג,א).","שנינו במשנה: \u0003\"האשה את בנה\u0004 והאשה את בעלה... מנחילין ולא נוחלין\". ותוהים: \u0003הא תו\u0004 \u0005[זה\u0006 הדין \u0005שוב]\u0006 \u0003למה לי\u0004 לשנותו? \u0003הא תנא ליה רישא\u0004 \u0005[הרי שנה אותו\u0006 כבר \u0005בתחילה],\u0006 ששנינו: \u0003האיש את אמו והאיש את אשתו\u0004 נוחלין ולא מנחילין, ומכאן מובן שהאשה אינה יורשת את בנה ואת בעלה!","ומשיבים, \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 בחזרה על מקרים אלו: שדינה של \u0003אשה\u0004 המנחילה \u0003את בנה,\u0004 הריהו \u0003דומיא\u0004 \u0005[\u0006ב\u0005דומה]\u0006 לדין \u0003אשה\u0004 המנחילה \u0003את בעלה: מה אשה\u0004 \u0003את בעלה\u0004 — \u0003אין הבעל יורש את אשתו בקבר,\u0004 כלומר, אם מת לפניה, אין אומרים שהוא עדיין נחשב כיורשה הראשון אף במותו, וקרוביו (כגון בניו מאשה אחרת) יורשים את אשתו, אלא קרובי האשה עצמה יירשוה. \u0003אף אשה את בנה\u0004 — \u0003אין הבן יורש את אמו בקבר,\u0004 שאם מת הבן ואחר כך מתה אמו — אינו יורשה במותו, \u0003להנחיל\u0004 על ידי כך את נכסיה \u0003לאחין\u0004 שיש לו \u0003מן האב,\u0004 אלא קרוביה יירשוה.","ובענין ירושת האב שהוזכרה במשנה \u0003אמר\u0004 \u0003ר' יוחנן משום\u0004 (בשם) \u0003ר' יהודה בן\u0004 \u0003ר' שמעון: דבר תורה\u0004 (מדין התורה) — \u0003האב יורש את בנו ואשה יורשת את בנה, שנאמר\u0004 בענין ירושת נחלה: \u0003\"מטות\"\u0004 (במדבר לו, ח), \u0003מקיש\u0004 (משווה) הכתוב \u0003מטה האם למטה האב\u0004 לכל ענין, \u0003מה מטה האב\u0004 — \u0003אב יורש את בנו, אף מטה האם\u0004 — \u0003אשה יורשת את בנה.\u0004"],["\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לר' יהודה בן שמעון,\u0004 והלא שנינו במשנתנו: \u0003האשה את בנה, והאשה את בעלה, ואחי האם\u0004 — \u0003מנחילין ולא נוחלין,\u0004 ובניגוד לדבריך! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003משנתנו איני יודע מי שנאה,\u0004 כלומר, כאיזו שיטה היא, שאינה עיקר להלכה.","ושואלים: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 ר' יוחנן: שיטת \u0003ר' זכריה בן הקצב היא,\u0004 שהוא \u0003לא דריש\u0004 \u0005[דורש]\u0006 את ההיקש של \u0003\"מטות\"\u0004 להשוות ירושת מטה האב ומטה האם (ראה לעיל בבא בתרא קיא, א)!","ומשיבים: \u0003לא מיתוקמא מתניתין\u0004 \u0005[אין משנתנו\u0006 יכולה להיות \u0005מועמדת,\u0006 מוסברת\u0005]\u0006 \u0003כ\u0004דעת \u0003ר' זכריה בן הקצב,\u0004 לפי \u0003דקתני\u0004 \u0005[ששנה]\u0006 בה גם \u0003ובני אחות, ותנא\u0004 \u0005[ושנה\u0006 החכם\u0005]\u0006 בהסבר הדברים: \u0003בני אחות ולא בנות אחות, ואמרינן\u0004 \u0005[ואמרנו]:\u0006 \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה,\u0006 נאמר הדבר\u0005]?\u0006 \u0003ואמר רב ששת: לקדם,\u0004 שגם בנכסי אחי האם, הבנים קודמים לבנות.","\u0003ואי סלקא דעתך מתניתין\u0004 \u0005[ואם עולה על דעתך\u0006 לומר כי \u0005משנתנו]\u0006 כשיטת \u0003ר' זכריה בן הקצב היא, הא\u0004 \u0005[הרי]\u0006 \u0003אמר: אחד הבן ואחד הבת שוין בנכסי האם,\u0004 וכיון שבני האחות יורשים מכח אמם, אין הבנים קרובים לאחי האם יותר מאשר הבנות!","ושואלים: \u0003ו\u0004ה\u0003תנא דידן\u0004 \u0005[שלנו],\u0006 \u0003ממה נפשך\u0004 \u0005[רצונך],\u0006 כלומר, באיזה אופן הוא דורש? \u0003אי דריש\u0004 \u0005[אם\u0006 הוא \u0005דורש]\u0006 את ההיקש של \u0003\"מטות\",\u0004 להשוות לגמרי ירושת אב ואם, אם כן \u0003אשה נמי\u0004 \u0005[גם כן]\u0006 \u0003תירש את בנה, אי לא דריש\u0004 \u0005[אם אינו דורש]\u0006 את ההיקש של \u0003\"מטות\", בן\u0004 ש\u0003קודם לבת בנכסי האם מנא ליה\u0004 \u0005[מנין לו]?\u0006 שהרי דבר זה נלמד בברייתא לעיל (בבא בתרא קיא,א) מ\"מטות\"!","ומשיבים: \u0003לעולם\u0004 תפרש כי התנא \u0003דריש\u0004 \u0005[דורש]\u0006 את ההיקש של \u0003\"מטות\", ושאני הכא\u0004 \u0005[ו\u0006אולם \u0005שונה כאן]\u0006 לענין ירושת האם את בנה, ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וכל בת ירשת נחלה\u0004 ממטות\u0003\"\u0004 (במדבר לו, ח), והוא מדייק מכאן: \u0003יורשת\u0004 נחלה של שני מטות, \u0003ואינה מורשת\u0004 נחלה לשני מטות, אלא למטה אביה. ולפיכך אין האם יורשת את בתה, ולא את בנה, שהרי אם היתה יורשת אותם נמצא שמורשת נחלה של משפחת בעלה (שירשו בנה או בתה) לקרוביה מצד אביה.","\u0003סדר נחלות כך הוא: \"איש כי ימות ובן אין לו והעברתם את\u0004 \u0003נחלתו לבתו\"\u0004 (במדבר כז, ח), ומכאן למדים ש\u0003בן קודם לבת.\u0004 יתר על כן, אם מת הבן, \u0003כל יוצאי יריכו של בן קודמין\u0004 אף הם \u0003לבת\u0004 בירושה. \u0003בת קודמת\u0004 בירושה \u0003לאחין\u0004 של הנפטר, ואף \u0003יוצאי יריכה של בת קודמין לאחין.\u0004 ה\u0003אחין\u0004 של הנפטר \u0003קודמין לאחי האב,\u0004 וכן \u0003יוצאי יריכן של אחין קודמין לאחי האב.\u0004","\u0003זה הכלל: כל הקודם בנחלה\u0004 — \u0003יוצאי יריכו קודמין\u0004 לרשת את הנחלה. \u0003והאב קודם לכל יוצאי יריכו,\u0004 כלומר, אם האב חי, הרי הוא יורש ראשון את בנו או בתו שמתו בלא זרע. ולא יוצאי יריכו, אחי הבן או הבת.","בענין הפסוק שהובא במשנה, וההלכות שנלמדו ממנו, \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר בתורה: \"ו \u0003בן\u0004 אין לו והעברתם את נחלתו לבתו\" (במדבר כז, ח) — \u0003אין לי\u0004 שקודם לבת \u0003אלא בן\u0004 בלבד, \u0003בן הבן, או בת הבן, או בן בת הבן מנין\u0004 שאף הם קודמים? — \u0003תלמוד לומר: \"אין לו\",\u0004 ואנו דורשים: \u0003עיין עליו,\u0004 כלומר, בדוק אם אין לו צאצאים, שאם יש לו — הם קודמים.","וכן נאמר \"ואם אין לו \u0003בת\u0004 ונתתם את נחלתו לאחיו\", \u0003אין לי\u0004 שקודמת לאחים \u0003אלא\u0004 ה\u0003בת\u0004 עצמה, \u0003בת הבת, ובן הבת, ובת בן הבת מנין\u0004 שקודמים לאחים? \u0003תלמוד לומר: \"אין לו\"\u0004 וכוונתו: \u0003עיין עליו,\u0004 בדוק אם אין לבת צאצאים, ואם יש לה — הם קודמים לאחים."],["\u0003הא כיצד\u0004 ניתן להמשיך עקרון זה של \"עיין עליו\" כאשר אין למת כל זרע? \u0003נחלה ממשמשת,\u0004 כלומר, נבדקת \u0003והולכת\u0004 גם לדורות הקודמים \u0003עד ראובן\u0004 ושאר ראשי שבטי ישראל. שאם אין כל צאצאים למת, עולים דור אחד למעלה לאביו, ואם איננו — לצאצאיו, אחי המת. ואם הם אינם וגם אין להם צאצאים — הולכים דור נוסף למעלה ולצאצאיו, וכך הלאה, ומבררים אם נשארו צאצאים לאחד מאבות האבות. וכך עשויה הנחלה להגיע עד לדור הראשון של השבט. ושואלים: \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 אם כן, נחלה ממשמשת והולכת \u0003עד יעקב,\u0004 ולא רק עד ראובן, שמא גם מן השבט כולו לא נשארו צאצאים! \u0003אמר אביי: גמירי\u0004 \u0005[למודים,\u0006 מקובלים אנו\u0005]\u0006 ש\u0003לא כלה\u0004 מישראל \u0003שבטא\u0004 \u0005[שבט]\u0006 שלם, אלא תמיד נשאר מישהו משבט זה.","\u0003אמר רב הונא אמר רב: כל האומר תירש בת עם בת הבן, אפילו\u0004 זה האומר הוא \u0003נשיא שבישראל\u0004 — \u0003אין שומעין לו, שאינן אלא מעשה צדוקין,\u0004 אלא יורשתו רק בת בנו. \u0003תניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 במגילת תענית, ברשימת הימים שנאסרו בהספד ותענית בגלל אירועים מיוחדים שאירעו בהם: \u0003בארבעה ועשרים בטבת תבנא לדיננא\u0004 \u0005[שבנו לדיננו],\u0006 כלומר, שהושב המשפט כפי הדין הראוי, כמסורת הפרושים, חכמי התורה. \u0003שהיו צדוקין אומרין: תירש הבת עם בת הבן,\u0004 ונהגו על פיהם משום שהיתה ידם תקיפה,","\u0003נטפל להן\u0004 (בא אצלם) \u0003רבן יוחנן בן זכאי,\u0004 \u0003אמר להם: שוטים, מנין זה לכם\u0004 שכך הדין? \u0003ולא היה\u0004 בהם \u0003אדם שהחזירו\u0004 (שהשיבו) \u0003דבר, חוץ מזקן אחד שהיה מפטפט\u0004 (מדבר דברים של כלום) \u0003כנגדו ו\u0004היה \u0003אומר\u0004 טענה זו: \u0003ומה בת בנו הבאה מכח בנו\u0004 — \u0003תירשנו, בתו הבאה מכחו\u0004 שלו — \u0003לא כל שכן\u0004 שתירשנו?","\u0003קרא\u0004 רבן יוחנן בן זכאי \u0003עליו את המקרא הזה: \"אלה בני שעיר החרי ישבי הארץ לוטן ושובל וצבעון וענה\"\u0004 (בראשית לו, כ), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"\u0004ו\u0003אלה בני צבעון ואיה וענה\"\u0004 (בראשית לו, כד), והכתובים סותרים זה את זה, שכן מכתוב אחד עולה שענה הוא בן שעיר, ואילו מן הכתוב השני עולה שענה הוא בן צבעון. \u0003אלא, מלמד שבא צבעון\u0004 בן שעיר \u0003על אמו והוליד\u0004 ממנה את \u0003ענה.\u0004 ומכל מקום, מכך שענה קרוי בן שעיר יש ללמוד שבני הבנים (ובנות הבנים) דינם כבנים.","ושואלים: \u0003ודלמא תרי\u0004 \u0005[ושמא שני]\u0006 \u0003ענה הוו\u0004 \u0005[היו],\u0006 האחד בן צבעון והאחר בן שעיר! \u0003אמר רבה\u0004 בתשובה לקושיה זאת: \u0003אמינא מלתא\u0004 \u0005[אומר אני דבר]\u0006 ש\u0003לא אמרה\u0004 אפילו \u0003שבור מלכא\u0004 \u0005[המלך],\u0006 ומסבירים: \u0003ומנו\u0004 \u0005[ומי הוא]\u0006 אותו \"שבור מלכא\"? שבוודאי לא התכוון למלך פרס הגוי, אלא לאדם מישראל — הרי זה \u0003שמואל,\u0004 שכך כינו אותו, משום גדולתו בתורה. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים\u0006 בגרסה אחרת\u0005],\u0006 \u0003אמר רב פפא: אמינא מלתא\u0004 \u0005[אומר אני דבר]\u0006 ש\u0003לא אמרה שבור מלכא\u0004 \u0005[המלך],\u0006 \u0003ומנו\u0004 \u0005[ומי הוא\u0006 זה\u0005]?\u0006 — \u0003רבה; אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"הוא ענה\u0004 אשר מצא את הימים במדבר ברעותו את החמורים לצבעון אביו\u0003\"\u0004 (בראשית לו, כד), לומר \u0003הוא ענה דמעיקרא\u0004 \u0005[שמתחילה]\u0006 שמדובר רק בענה אחד.","וממשיכה הברייתא: \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו זקן צדוקי לרבן יוחנן בן זכאי: \u0003רבי, בכך אתה פוטרני?\u0004 כלומר, בדרשה שכזו רוצה אתה לפרוך אותו קל וחומר שהבאתי? והלא גם אני סבור שבן הבן יורש את זקנו ואפילו במקום הבת, ואולם בת הבן עדיין תירש עם בת המת! \u0003אמר לו: שוטה,\u0004"],["\u0003ולא\u0004 תהא סבור ש\u0003תהא תורה שלמה שלנו\u0004 מדרשת הכתובים, \u0003כשיחה בטלה שלכם.\u0004 ומדוע דברי הזקן הם שיחה בטלה — משום שהקל וחומר שאמר הוא מופרך מעיקרו, שכן אפשר לומר: \u0003מה לבת בנו\u0004 — \u0003שכן יפה כחה במקום\u0004 (יחד עם) \u0003האחין\u0004 של אביה, שהרי היא נוטלת את חלק אביה, בן אבי אביה המת, \u0003תאמר בבתו\u0004 — \u0003שהורע כחה במקום אחין\u0004 שבמקום שיש אחים, אין הבת יורשת כלל. ומכאן ראיה שכוח הירושה של בת הבן גדול מזה של הבת. \u0003ו\u0004כיון שלא מצאו הצדוקים תשובה לדבר, \u0003נצחום,\u0004 גברו עליהם חכמים בויכוח, וחזרו לדין ישראל הישן, \u0003ואותו היום עשאוהו יום טוב.\u0004","ובענין זה של ירושת בת הבן עם האחים, לאחר שכמעט השמידו שבטי ישראל את שבט בנימין כולו בעקבות מעשה פילגש בגבעה, נאמר: \u0003\"\u0004ויאמרו זקני העדה מה נעשה לנותרים... \u0003ויאמרו ירשת פלטה לבנימן ולא ימחה שבט מישראל\"\u0004 (שופטים כא, טז–יז),","\u0003אמר\u0004 \u0003ר' יצחק דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' אמי: מלמד, שהתנו על שבט בנימין שלא תירש בת הבן עם האחין,\u0004 כדי שלא תעבור נחלה משבט בנימין על ידה. והיתה זו תקנה לשעתה מפני שהיה השבט מועט ביותר במספר אנשיו.","אגב העיסוק בירושת מי שאין לו בן, מביאים מה ש\u0003אמר\u0004 \u0003ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחאי: כל שאינו מניח בן ליורשו\u0004 — \u0003הקדוש ברוך הוא מלא עליו עברה\u0004 (כעס). ומנין לנו כן — \u0003כתיב הכא\u0004 \u0005[נאמר כאן\u0006 בפרשת ירושות\u0005]:\u0006 \u0003\"והעברתם את נחלתו\u0004 לבתו\u0003\"\u0004 (במדבר כז, ח), \u0003וכתיב התם\u0004 \u0005ונאמר שם\u0006 ביום ה' לעתיד\u0005]:\u0006 \u0003\"יום עברה היום ההוא\"\u0004 (צפניה א, טו). הרי שמשתמשים בענין הסבת נחלה באותו שורש של \"עבר\", שמשמעו גם לשון כעס.","ועוד בענין זה נאמר: \u0003\"אשר אין חליפות למו ולא יראו אלהים\"\u0004 (תהלים נה, כ), \u0003ר' יוחנן ור' יהושע בן לוי\u0004 נחלקו בפירוש פסוק זה, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 \"אשר אין חליפות למו\" כוונתו \u0003כל שאינו מניח בן\u0004 להחליפו. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: כל שאינו מניח תלמיד\u0004 שימלא את מקומו.","ומעירים: \u0003תסתיים\u0004 \u0005[תוגדר,\u0006 תתברר\u0005]\u0006 ש\u0003ר' יוחנן\u0004 הוא ש\u0003אמר\u0004 שהכוונה לזה שאינו מניח \u0003תלמיד, דאמר\u0004 \u0005[ש\u0006כך היה \u0005אומר]\u0006 \u0003ר' יוחנן\u0004 לאחר שמתו בניו בחייו, כשהיה מנחם אחרים: \u0003דין גרמיה דעשיראה ביר\u0004 \u0005[זוהי העצם של בני העשירי],\u0006 שלא נשארו לו בנים נוספים. וכיון שהיה מזכיר את הדבר, בלי להתבייש בו, משמע שהיה סבור שמי שלא הניח בן אחריו אינו בכלל \"ולא יראו אלוקים\", ואם כן \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 ש\u0003ר' יוחנן\u0004 הוא ש\u0003אמר תלמיד.\u0004","ושואלים: \u0003ומ\u0004כיון ש\u0003ר' יוחנן\u0004 הוא ש\u0003אמר\u0004 שפירוש הפסוק הוא למי שאינו מניח \u0003תלמיד,\u0004 מכאן ש\u0003ר' יהושע בן לוי\u0004 הוא ש\u0003אמר\u0004 מי שאינו מניח \u0003בן?\u0004","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' יהושע בן לוי לא אזיל\u0004 \u0005[היה הולך]\u0006 \u0003ל\u0004סתם \u0003בי טמיא\u0004 \u0005[בית האבל]\u0006 \u0003אלא\u0004 רק \u0003לבי מאן דשכיב\u0004 \u0005[לבית מי שמת]\u0006 \u0003בלא בני\u0004 \u0005[בנים],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בכו בכה להלך\"\u0004 (ירמיהו כב, י), \u0003ואמר רב יהודה אמר רב:\u0004 כוונתו \u0003להולך בלא בן זכר,\u0004 ואם אדם כזה אינו נחשב ירא אלקים, בוודאי לא היה משתדל ללכת ולנחם דווקא אדם כזה. \u0003אלא\u0004 יש לומר להיפך: \u0003ר' יהושע בן לוי הוא\u0004 ש\u0003אמר\u0004 מי שלא השאיר \u0003תלמיד.\u0004","ומקשים: \u0003ומ\u0004כיון ש\u0003ר' יהושע בן לוי הוא\u0004 ש\u0003אמר\u0004 מי שלא השאיר \u0003תלמיד,\u0004 מכאן ש\u0003ר' יוחנן\u0004 הוא ש\u0003אמר\u0004 שמי שאינו מניח \u0003בן\u0004 אינו ירא אלוקים, ואם כן","\u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' יוחנן\u0004 על דברי \u0003ר' יוחנן\u0004 שהיה מראה את עצם בנו! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 שהיה מנחם אחרים בעצם בנו — הרי זו דעתו \u0003דידיה\u0004 \u0005[שלו],\u0006 שהיה סבור: זה שאינו מניח תלמיד. \u0003הא\u0004 \u0005[זו]\u0006 שאמר שאינו מניח בן — הרי זו דעתו \u0003דרביה\u0004 \u0005[של רבו].\u0006","\u0003(סימן\u0004 לדרשות הבאות של ר' פנחס בן חמא: \u0003הדד עני וחכם).\u0004","ועוד בענין מי שלא הניח בן, \u0003דרש\u0004 \u0003ר' פנחס בן חמא, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"והדד שמע במצרים כי שכב דוד עם אבתיו וכי מת יואב שר הצבא\"\u0004 (מלכים א יא, כא)? \u0003מפני מה\u0004 באותו פסוק עצמו \u0003בדוד נאמרה בו\u0004 לשון \u0003\"שכיבה\", וביואב נאמרה בו\u0004 לשון \u0003\"מיתה\"?\u0004 ומסבירים: \u0003דוד שהניח בן\u0004 — \u0003נאמרה בו שכיבה,\u0004 שאין זה מוות גמור, \u0003יואב שלא הניח בן\u0004 — \u0003נאמרה בו מיתה.\u0004","ותוהים: \u0003ו\u0004כי \u0003יואב לא הניח בן? והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"מבני יואב עבדיה בן יחיאל\"\u0004 (עזרא ח, ט)! \u0003אלא,\u0004 יש לתקן ולומר כך: \u0003דוד שהניח בן כמותו\u0004 שהיה ממלא מקומו בגדולה — \u0003נאמרה בו\u0004 לשון \u0003\"שכיבה\"\u0004 בלבד, \u0003יואב שלא הניח בן כמותו\u0004 — \u0003נאמרה בו\u0004 לשון \u0003\"מיתה\".\u0004","כיון שהבאנו דרשה של חכם זה מביאים דרשה אחרת בשמו, \u0003דרש\u0004 \u0003ר' פנחס בן חמא: קשה עניות בתוך ביתו של אדם יותר מחמשים מכות, שנאמר: \"חנני חנני אתם רעי כי יד אלוה נגעה בי\"\u0004 (איוב יט, כא), \u0003וקא אמרי ליה חבריה\u0004 \u0005[והיו אומרים לו חביריו\u0006 לאיוב\u0005]:\u0006 \u0003\"השמר אל תפן אל און כי על זה בחרת מעני\"\u0004 (איוב לו, כא). כלומר, אל תדבר דברים קשים כלפי מעלה, שהרי מוטב לך לבחור באלו מבעוני.","ועוד \u0003דרש\u0004 \u0003ר' פנחס בר חמא: כל שיש לו חולה בתוך ביתו, ילך אצל חכם ויבקש עליו רחמים\u0004 שיתרפא, \u0003שנאמר: \"חמת מלך מלאכי מות ואיש חכם יכפרנה\"\u0004 (משלי טז, יד). שאם כעס ה' (\"חמס מלך\") על אדם, ושלח עליו חולי (\"מלאכי מוות\") — ילך לחכם כדי שיכפר ויסיר מעליו כעס זה.","שנינו במשנה, \u0003זה הכלל: כל הקודם בנחלה\u0004 — \u0003יוצאי ירכו קודמין; והאב קודם לכל יוצאי ירכו. בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא\u0004 שאלה זו: \u0003אבי האב ואחי האב, כגון אברהם וישמעאל,\u0004 אם היו צריכים לבוא לרשת \u0003בנכסי עשו\u0004 בן יצחק, אם היה מת בלא בנים, \u0003איזה מהן קודם? אמר רבא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 שמפורש הדבר במשנה: \u0003האב קודם לכל יוצאי ירכו,\u0004 משמע שאברהם קודם. ומעירים: \u0003ורמי בר חמא\u0004 עצמו, מדוע שאל שאלה זו? הרי ודאי ידע את המשנה!"],["ומשיבים: \u0003אגב חורפיה\u0004 \u0005[חריפותו,\u0006 מהירותו\u0005]\u0006 \u0003לא עיין בה\u0004 אף שהיא מקור מפורש.","ועוד בענין זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא: אבי האב ואחיו\u0004 של הנפטר, \u0003כגון אברהם ויעקב\u0004 הבאים לרשת \u0003בנכסי עשו, איזה מהן קודם? אמר רבא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה ששנינו: \u0003האב קודם לכל יוצאי יריכו,\u0004 משמע שאברהם קודם לכל יוצאי יריכו, ובכללם גם יעקב! ושואלים: \u0003ורמי בר חמא\u0004 מה הוא אומר על ראיה זו לבעייתו? ומשיבים: לדעתו יש לפרש כי הכוונה דווקא ל\u0003יוצאי יריכו שלו, ולא יוצאי יריכו של בנו.\u0004","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר\u0006 לומר\u0005],\u0006 \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנה\u0006 במשנה\u0005],\u0006 \u0003זה הכלל: כל הקודם בנחלה\u0004 — \u0003יוצאי יריכו קודמין, ו\u0004הרי \u0003אילו איתיה\u0004 \u0005[ישנו]\u0006 \u0003ליצחק,\u0004 היה \u0003יצחק קודם\u0004 בנחלה לאברהם, \u0003השתא נמי דליתיה\u0004 \u0005[עכשיו גם כן שאיננו,\u0006 שמת\u0005]\u0006 \u0003יצחק\u0004 — \u0003יעקב קודם,\u0004 שהרי הבן קודם לכל היורשים. ומעירים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכך היא ההלכה.","\u0003בנות צלפחד נטלו שלשה חלקים בנחלה\u0004 בארץ ישראל, ואלו הם: נטלו את \u0003חלק אביהן שהיה עם יוצאי מצרים, ו\u0004כן נטלו את \u0003חלקו\u0004 של צלפחד \u0003עם אחיו בנכסי חפר\u0004 שגם לו היה חלק בארץ. \u0003ו\u0004עוד חלק שצריך היה אביהן לקבל, משום \u0003שהיה בכור\u0004 ש\u0003נוטל שני חלקים\u0004 מנחלת חפר."],["ומעירים: במשנתנו שאמרה שבנות צלפחד נטלו שלושה חלקים, \u0003תנן\u0004 \u0005[שנינו]\u0006 \u0003כ\u0004שיטת \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי \u0003ליוצאי מצרים נתחלקה הארץ,\u0004 כלומר, אלה שבפועל נחלו את הארץ קיבלו את חלקם בנחלה לפי החלוקה בין יוצאי מצרים,","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 שבה מבואר שענין זה שנוי במחלוקת, \u0003ר' יאשיה אומר: ליוצאי מצרים נתחלקה הארץ, שנאמר: \"לשמות מטות אבתם ינחלו\"\u0004 (במדבר כו, נה), לומר שירושת הארץ היא לפי יוצאי מצרים. שכל אחד מיוצאי מצרים זכה בחלק מסויים, והבאים לארץ מצאצאיו, יהיו כמה שיהיו, הם מתחלקים ביניהם באותה נחלה. \u0003אלא מה אני מקיים \"לאלה תחלק הארץ בנחלה\"\u0004 (במדבר כו, נג), שמשמעה דווקא לאלה שנמנו קודם לכן (במדבר פרק כו), והם הבאים אל הארץ? הכוונה במלה \u0003\"לאלה\"\u0004 היא: למי שהוא \u0003כאלה,\u0004 כמו אלו המנויים, מבן עשרים שנה ומעלה, \u0003להוציא,\u0004 למעט מכלל חלוקת הארץ \u0003את הטפלים\u0004 (ילדים קטנים), שלא היו בני עשרים בשעה שיצאו ממצרים, שאלה לא קיבלו חלק לעצמם.","\u0003ר' יונתן אומר: לבאי הארץ נתחלקה הארץ, שנאמר: \"לאלה תחלק הארץ בנחלה\", אלא מה אני מקיים \"לשמות מטות אבתם ינחלו\"?\u0004 — \u0003משונה נחלה זו מכל נחלות שבעולם, שכל נחלות שבעולם\u0004 — קרובי המשפחה ה\u0003חיין יורשין\u0004 את ה\u0003מתים, וכאן\u0004 ה\u0003מתים יורשין\u0004 את ה\u0003חיין.\u0004 שלאחר שנתחלקה הארץ בין באי הארץ (החיים), כאילו מעבירים את הנחלה לאבותיהם (המתים) היוצאים ממצרים, וחוזרים הצאצאים ויורשים אותם.","\u0003אמר רבי: אמשול לך משל, למה הדבר דומה?\u0004 — \u0003לשני אחין כהנים שהיו בעיר אחת. לאחד יש לו בן אחד, ואחד יש לו שני בנים, והלכו\u0004 הבנים \u0003לגורן\u0004 ליטול תרומה, \u0003זה שיש לו בן אחד\u0004 — \u0003נוטל חלק אחד\u0004 שקיבל בנו, \u0003וזה שיש לו שני בנים\u0004 — \u0003נוטל שני חלקים\u0004 שקיבלו שני בניו. \u0003ומחזירין\u0004 שני האחים את הכל \u0003אצל אביהן\u0004 (הסב) \u0003וחוזרין\u0004 האחים \u0003וחולקין בשוה,\u0004 שכל אחד מהם מקבל חלק ומחצה, וכשהם חוזרים ומחלקים את התרומה לבניהם, נמצא הבן היחיד מקבל כל חלקו של אביו, ושני הבנים של האח האחר מתחלקים במה שקיבל אביהם.","\u0003ר' שמעון בן אלעזר אומר:\u0004"],["גם \u0003לאלו ו\u0004גם \u0003לאלו נתחלקה הארץ, כדי לקיים שני מקראות הללו; הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 היה הדבר? אם \u0003היה\u0004 האיש \u0003מיוצאי מצרים\u0004 — \u0003נוטל חלקו עם יוצאי מצרים.\u0004 ואם נולד האיש במדבר, או שהיה פחות מבן עשרים ביציאתו ממצרים, ו\u0003היה מבאי הארץ\u0004 — \u0003נוטל חלקו עם באי הארץ.\u0004 היה \u0003מכאן ומכאן\u0004 — \u0003נוטל חלקו מכאן ומכאן.\u0004","ועוד בענין זה של חלוקת הארץ: עשרת ה\u0003מרגלים\u0004 שאיבדו חלקם בנחלת הארץ — \u0003יהושע וכלב נטלו חלקם.\u0004 \u0003מתלוננים ועדת קרח\u0004 — \u0003לא היה להם חלק\u0004 כלל \u0003בארץ, הבנים\u0004 של המרגלים והמתלוננים, שלא קיבלו חלק בארץ מאבותיהם, \u0003נטלו\u0004 חלק בארץ \u0003בזכות אבי אביהן ובזכות אבי אמותיהן\u0004 שהיו בין יוצאי מצרים. עד כאן לשון הברייתא, ומעתה דנים במה שנאמר בה.","ותחילה שואלים: \u0003מאי משמע\u0004 \u0005[מהי המשמעות],\u0006 כיצד מובן הדבר מן המקרא \u0003דהאי\u0004 \u0005[ש\u0006כתוב \u0005זה]:\u0006 \u0003\"לשמות מטות אבתם\"\u0004 (במדבר כו, נה), \u0003ביוצאי מצרים כתיב\u0004 \u0005[נאמר]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003לשבטים קאמר לה\u0004 \u0005[אומר אותה]\u0006 שיחלקו את הנחלות לפי מספר השבטים, לשנים עשר חלקים שווים, ולא לפי יוצאי מצרים! ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ונתתי אתה לכם מורשה אני ה'\"\u0004 (שמות ו, ח), וכתוב זה משמעו שהארץ \u0003ירושה היא לכם מאבותיכם, ו\u0004הרי \u0003ליוצאי מצרים קאמר להו\u0004 \u0005[אמר להם]\u0006 את הדברים הללו. משמע מכאן שיוצאי מצרים הם שזכו בנחלת הארץ, ומהם מקבלים בניהם אחריהם.","\u0003(סימן\u0004 לדיונים הבאים הוא: \u0003לרב\u0004 תרבה נחלתו, בנות \u0003צלפחד, ו\u0004בני \u0003יוסף, איכפל\u0004 יהושע וכלב, חבלי \u0003מנשה\u0004 בתי אבות \u0003יחשב).\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003ליוצאי מצרים נתחלקה הארץ, היינו דכתיב\u0004 \u0005[זהו\u0006 מה \u0005שנאמר\u0006 בכתוב\u0005]:\u0006 \u0003\"לרב תרבה נחלתו ולמעט תמעיט נחלתו\"\u0004 (במדבר כו, נד), שיש חידוש בדבר, שאף שנשתנה מספרם בכניסה לארץ — מכל מקום קיבלו לפי היותם \"רב\" או \"מעט\" ביציאתם ממצרים."],["\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003לבאי הארץ\u0004 נתחלקה הארץ, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הציווי \u0003\"לרב תרבו נחלתו\"\u0004 (במדבר כו, נד)? הרי אם מחולקת הארץ בשווה לכל באי הארץ, מובן הדבר מאליו! ואומרים: אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","\u0003ו\u0004עוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003ליוצאי מצרים\u0004 נתחלקה הארץ, \u0003היינו דקא צווחן\u0004 \u0005[זהו\u0006 הטעם \u0005שהיו צווחות]\u0006 \u0003בנות צלפחד\u0004 ורצו גם הן חלק בירושת הארץ, שהרי צלפחד אביהן היה מיוצאי מצרים. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003לבאי הארץ\u0004 נתחלקה הארץ, \u0003אמאי צווחן\u0004 \u0005[מדוע צווחו]?\u0006 \u0003הא ליתיה דלשקול\u0004 \u0005[הרי\u0006 צלפחד אביהן \u0005איננו\u0006 כאן, כדי \u0005שיטול]\u0006 את חלקו בנחלה!","אמר לו אביי: \u0003אלא\u0004 בוודאי לדעת מי שסבור כן, הכוונה היא \u0003ל\u0004ענין \u0003חזרה,\u0004 שהרי כפי שראינו בברייתא, לדעה זו מחזירים באי הארץ את הנחלה ליוצאי מצרים, ומכוחם חוזרים וחולקים, \u0003ו\u0004אף בנות צלפחד דרשו \u0003ליטול\u0004 חלק \u0003בנכסי חפר\u0004 אבי צלפחד.","ועוד שואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003ליוצאי מצרים\u0004 נתחלקה הארץ, \u0003היינו דקא צווחן\u0004 \u0005[זהו\u0006 הטעם \u0005שהיו צווחים]\u0006 \u0003בני יוסף\u0004 שהתרבו ביותר מזמן שיצאו ממצרים ועד הכניסה לארץ, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וידברו בני יוסף\u0004 את יהושע לאמר מדוע נתתה לי נחלה גורל אחד וחבל אחד ואני עם רב עד אשר עד כה ברכני ה'\u0003\"\u0004 (יהושע יז, יד), \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003לבאי הארץ\u0004 נתחלקה הארץ, \u0003מאי קא צווחי\u0004 \u0005[מדוע צווחו]\u0006 בני יוסף? והרי \u0003כולהו שקול\u0004 \u0005[כולם נטלו\u0006 בשווה\u0005]\u0006 כל אחד ואחד מבאי הארץ!","ומשיבים: \u0003משום טפלים\u0004 (תינוקות) הקטנים מבני עשרים \u0003דהוו נפישי להו\u0004 \u0005[שהיו מרובים להם]\u0006 יותר מאשר לשבטים אחרים, והם דאגו שלא תהא הנחלה מספיקה לכל ילדיהם.","בעקבות הדיון בטענותיהם של בנות צלפחד ובני יוסף \u0003אמר אביי, שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003לא הוה חד\u0004 \u0005[היה אחד]\u0006 מבין כל באי הארץ ש\u0003לא שקיל\u0004 \u0005[נטל]\u0006 חלק בארץ ישראל, \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר ש\u0003הוה חד\u0004 \u0005[\u0006ש\u0005היה\u0006 שם \u0005אחד]\u0006 ש\u0003לא שקיל\u0004 \u0005[נטל],\u0006 \u0003איבעי ליה למצווח\u0004 \u0005[צריך היה לו לצווח]\u0006 ולהתאונן לפני משה או לפני יהושע על שלא קיבל נחלה, כפי שעשו בנות צלפחד ובני יוסף. \u0003וכי תימא\u0004 \u0005[ואם\u0006 תרצה \u0005לומר]:\u0006 מי ש\u0003צווח ואהני כתביה קרא\u0004 \u0005[והועיל\u0006 הדבר \u0005כתבו המקרא],\u0006 זה ש\u0003צווח ולא אהני\u0004 \u0005[הועיל]\u0006 \u0003לא כתביה קרא\u0004 \u0005[כתבו המקרא],\u0006 ואולי היו כאלה שצווחו על שלא קיבלו נחלה, אלא שגם לאחר שהתלוננו לא ניתן להם דבר — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בני יוסף דצווחי\u0004 \u0005[שצווחו]\u0006 \u0003ולא אהני\u0004 \u0005[הועיל\u0006 הדבר\u0005]\u0006 \u0003ו\u0004בכל זאת \u0003כתבינהו קרא\u0004 \u0005[כתב אותם המקרא],\u0006 ואם לא נכתבו במקרא עוד טענות אחרות, משמע שכל אחד קיבל חלקו בארץ ישראל.","ודוחים: מבני יוסף אין ראיה, כי \u0003התם\u0004 \u0005[שם]\u0006 נכתב הפסוק לא כדי להודיענו את טענתם, אלא \u0003עצה טובה קא משמע לן\u0004 \u0005[השמיע לנו],\u0006 \u0003דאיבעי ליה לאיניש לאיזדהורי מעינא בישא\u0004 \u0005[שצריך לו לאדם להיזהר מעין רעה].\u0006 \u0003והיינו דקאמר להו\u0004 \u0005[וזהו שאמר להם\u0006 לבני יוסף\u0005]\u0006 \u0003יהושע\u0004 בתשובה לדרישתם, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר אלהם יהושע אם עם רב אתה עלה לך היערה\u0004 ובראת לך שם. . .\" (יהושע יז, טו), שיכרתו את היער וישבו שם. \u0003אמר להו\u0004 \u0005[להם]:\u0006 כיון שאתם רבים כל כך, \u0003לכו והחבאו עצמכם ביערים\u0004 כדי \u0003שלא תשלוט בכם עין רע.\u0004"],["\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אנן מזרעא\u0004 \u0005[אנו מזרע]\u0006 \u0003יוסף\u0004 ש\u0003לא שלטא ביה עינא בישא\u0004 \u0005[שולטת בו עין רעה]\u0006 ואין אנו צריכים להתחבא מפני עין הרע, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בברכת יעקב ליוסף: \u0003\"בן פרת יוסף בן פרת עלי עין\"\u0004 (בראשית מט, כב), \u0003ואמר\u0004 \u0003ר' אבהו: אל תקרי\u0004 (תקרא) \u0003\"עלי עין\" אלא \"עולי עין\",\u0004 כלומר, שבניו הם מעל לעין, שאין עין רעה מסוגלת להזיק להם.","\u0003ר' יוסי בר' חנינא אמר: מהכא\u0004 \u0005[מכאן]\u0006 יש ראיה שבני יוסף אין עין רעה שולטת בהם, שנאמר בברכת יעקב ליוסף על בניו: \u0003\"וידגו לרב בקרב הארץ\"\u0004 (בראשית מח, טז), והשוואה זו לדגים מלמדת: \u0003מה דגים שבים\u0004 — \u0003מים מכסים עליהם ו\u0004לכן \u0003אין העין שולטת בהם, אף זרעו של יוסף\u0004 — \u0003אין העין שולטת בהם.\u0004","שנינו בברייתא ש\u0003מרגלים\u0004 — \u0003יהושע וכלב נטלו חלקם\u0004 בירושת הארץ. ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שהם נטלו את חלק המרגלים? \u0003אמר עולא,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ויהושע בן נון וכלב בן יפנה חיו מן האנשים ההם\"\u0004 (במדבר יד, לח), ויש לשאול: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חיו\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003חיו ממש,\u0004 והכתוב מציין שהם היחידים שנשארו בחיים מבין כל שנים עשר המרגלים, \u0003והא כתיב קרא אחרינא\u0004 \u0005[והרי נאמר כתוב אחר]:\u0006 \u0003\"ולא נותר מהם איש כי אם כלב בן יפנה ויהושע בן נון\"\u0004 (במדבר כו, סה)! \u0003אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חיו\"?\u0004 — כוונתו \u0003שחיו בחלקם,\u0004 כלומר, שהם נהנו מחלקם של המרגלים.","ועוד שנינו בברייתא: \u0003מתלוננין ועדת קרח לא היה להן\u0004 כלל \u0003חלק בארץ.\u0004 ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא אחרת\u0005]\u0006 ש\u0003מרגלים, מתלוננים ועדת קרח\u0004 — \u0003יהושע וכלב נטלו חלקם.\u0004 הרי שהיה להם חלק, אלא שנלקח מהם! ודוחים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 בברייתא השניה\u0005]\u0006 \u0003מקיש\u0004 (משווה) \u0003מתלוננים למרגלים,\u0004 וכשם שלמרגלים היה חלק בארץ אף למתלוננים היה חלק, \u0003מר\u0004 \u0005[חכם זה,\u0006 בברייתא הראשונה\u0005]\u0006 שאינו סבור כן, \u0003לא מקיש מתלוננים למרגלים.\u0004 והיכן הם מצויים יחד בכתובים, כך שאפשר להקישם זה לזה?","— \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בפרשת בנות צלפחד, כשביקשו נחלה: \u0003\"אבינו מת במדבר\"\u0004 (במדבר כז, ג) — \u0003זה צלפחד, \"והוא לא היה בתוך העדה\"\u0004 (במדבר כז, ג) — \u0003זה עדת מרגלים, \"הנועדים על ה'\"\u0004 — \u0003אלו מתלוננים, \"בעדת קרח\"\u0004 — \u0003כמשמעו,\u0004 לומר שאין כל סיבה לכך שלא יקבל צלפחד את חלקו בארץ.","ואם כן, \u0003מר\u0004 \u0005[חכם זה]\u0006 \u0003מקיש מתלוננים למרגלים\u0004 לומר שאף למתלוננים היה חלק בארץ, כמו למרגלים, אלא שיהושע וכלב נטלו חלקם, \u0003ומר\u0004 \u0005[וחכם זה]\u0006 \u0003לא מקיש מתלוננים למרגלים.\u0004","\u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: ולמאן דמקיש\u0004 \u0005[ול\u0006דעת \u0005מי שמשווה]\u0006 \u0003מתלוננים למרגלים, איכפול\u0004 \u0005[התאמצו]\u0006 \u0003יהושע וכלב וירתו לכולה\u0004 \u0005[וירשו את כל]\u0006 \u0003ארץ ישראל?\u0004 שהרי כל ישראל בהיותם במדבר התלוננו! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מתלוננים שבעדת קרח קאמרינן\u0004 \u0005[אומרים אנו],\u0006 שאין אנו מתכוונים לכל המתלוננים שבישראל, אלא לאותם מתלוננים שהיו בעדת קרח, שהיו רק מספר קטן של אנשים.","ושבים לדיון במחלוקת שבברייתא. \u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003ליוצאי מצרים נתחלקה הארץ, היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 בנחלת שבט מנשה: \u0003\"ויפלו חבלי מנשה עשרה...\u0004 כי בנות מנשה נחלו נחלה בתוך בניו\u0003\"\u0004 (יהושע יז, ה–ו), \u0003שיתא דשיתא\u0004 \u0005[שישה\u0006 חבלים \u0005של שישה]\u0006 \u0003בתי אבות\u0004 של מנשה המנויים בפסוק קודם (יהושע יז, ב), \u0003וארבעה\u0004 חלקים \u0003דידהו\u0004 \u0005[שלהן],\u0006 שירשו מכח אביהן, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003עשרה\u0004 חלקים.","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003לבאי הארץ\u0004 נתחלקה, \u0003תמניא הוא דהוו\u0004 \u0005[שמונה\u0006 חלקים \u0005הם שהיו],\u0006 ובאופן זה: \u0003שיתא דשיתא\u0004 \u0005[שישה של שישה]\u0006 \u0003בתי אבות, ותרי דידהו\u0004 \u0005[ושנים שלהן]\u0006 שקיבלו מנכסי חפר אבי אביהן, שהרי צלפחד היה בנו בכורו — \u0003הא תמניא\u0004 \u0005[הרי שמונה]!\u0006","ודוחים את הקושיה: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 כי \u0003ליוצאי מצרים נתחלקה הארץ,\u0004 והלא \u0003תשעה\u0004 חלקים \u0003הוו\u0004 \u0005[היו]\u0006 ולא יותר, שהרי במשנה נאמר שבנות צלפחד נטלו שלושה חלקים בארץ, ולא ארבעה! \u0003אלא מאי אית\u0004 \u0005[מה יש]\u0006 \u0003לך למימר\u0004 \u0005[לומר]\u0006 ולהסביר כיצד קיבלו בנות צלפחד עוד חלק נוסף? — ש\u0003חד אחא דאבא הוה להו\u0004 \u0005[אח אחד של אב\u0006 של צלפחד \u0005היה להן],\u0006 שלא היו לאותו אח ילדים, והם ירשו את נחלתו, כבנות צלפחד, בתוך אחיו האחרים. אם כן \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר לדעת מי שסבור שלבאי הארץ נתחלקה הארץ, כי \u0003תרי אחי דאבא הוה להו\u0004 \u0005[שני אחים של אב היו להן],\u0006 והן ירשו עוד שתי נחלות. ומנין לנו לפרש שנטלו נחלה של אחי אביהן?","— \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"נתן תתן להם\u0004 אחוזת נחלה\u0003\"\u0004 (במדבר כז, ז) — \u0003זו נחלת אביהן, \"בתוך אחי אביהן\"\u0004 (במדבר כז, ז) — \u0003זו נחלת אבי אביהן, \"והעברת את נחלת אביהן להן\"\u0004 (במדבר כז, ז) — \u0003זו חלק בכורה\u0004 שהיה לצלפחד.","\u0003ר' אליעזר בן יעקב אומר: אף חלק אחי אביהם נטלו, שנאמר: \"נתן תתן\"\u0004 שהיא לשון ריבוי, המלמדת שנוסף לנתינה המפורשת יש עוד נתינה נוספת. ומעירים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]:\u0006 \u0003תרי אחי דאבא הוה להו\u0004 \u0005[שני אחים של אב היו להן],\u0006 כלומר, זה הסבור כי לבאי הארץ נתחלקה הארץ, צריך לומר כי \u0003ההוא\u0004 \u0005[אותו\u0006 חלק\u0005]\u0006 נוסף, \u0003מ\u0004מה שנאמר \u0003\"\u0004נתן תתן להם \u0003אחזת נחלה\" נפקא\u0004 \u0005[יוצא\u0006 הדבר\u0005],\u0006 שיכול היה לכתוב רק \"נחלה\", ויש בזה ריבוי נוסף, שהיה להם עוד שטח לנחלה. וממשיכים לדון בפסוק \"ויפלו חבלי מנשה עשרה\".","\u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: קרא מאי קא חשיב\u0004 \u0005[הכתוב\u0006 את \u0005מה הוא מחשיב],\u0006 את מה הוא מונה? \u0003אי טפלים קא חשיב\u0004 \u0005[אם\u0006 את \u0005הילדים הקטנים הוא מונה],\u0006 כלומר, אלו שלא זכו לנחלה מכח עצמם, אלא כיורשי אבותם — \u0003טובא הוו\u0004 \u0005[הרבה\u0006 יותר \u0005היו]\u0006 ולא רק בנות צלפחד! \u0003אי\u0004 \u0005[אם]\u0006 \u0003בתי אבות קחשיב\u0004 \u0005[הוא מונה],\u0006 הלא רק \u0003שיתא הוו\u0004 \u0005[שישה\u0006 בלבד \u0005היו]\u0006 כמבואר באותו פרק!"],["\u0003לעולם בתי אבות קא חשיב\u0004 \u0005[הוא מונה]\u0006 ולא טפלים, \u0003ו\u0004זה שנמנו גם הנחלות שנתנו לבנות צלפחד — \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 ש\u0003בנות צלפחד נטלו חלק בכורה\u0004 של אביהן בנכסי חפר אביו, \u0003אלמא\u0004 \u0005[\u0006ו\u0005מכאן\u0006 יש ללמוד\u0005]\u0006 ש\u0003ארץ ישראל\u0004 נחשבת כמי ש\u0003מוחזקת היא\u0004 כבר למי שקיבל בה נחלה, למרות שעדיין לא הגיעה לידו בפועל. שהרי אין הבכור נוטל אלא בדבר שמוחזק בידי אביו, ולא בדבר הראוי לו להיות לנחלה, ולמרות זאת זכה צלפחד (עבור בנותיו) בחלק הבכורה שבנכסי חפר.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003והבנים\u0004 של המרגלים והמתלוננים \u0003נטלו\u0004 חלק בארץ \u0003בזכות אבי אביהם ובזכות אבי אמותיהן.\u0004 ומתקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא אחרת\u0005]\u0006 שהבנים של המרגלים והמתלוננים נטלו \u0003בזכות עצמן!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 הברייתא ששנינו סבורה שבזכות אביהם נטלו — \u0003כמאן דאמר\u0004 \u0005[כ\u0006דעת \u0005מי שאומר]\u0006 שנתחלקה הארץ \u0003ליוצאי מצרים,\u0004 \u0003הא\u0004 \u0005[זו]\u0006 הברייתא ששנינו שבזכות עצמם נטלו סבורה — \u0003כמאן דאמר\u0004 \u0005[כ\u0006דעת \u0005מי שאומר]\u0006 ש\u0003לבאי הארץ\u0004 נתחלקה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא והא\u0004 \u0005[זו וזו]\u0006 כשיטת האומר כי \u0003לבאי הארץ\u0004 נתחלקה, \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 שנויה במי \u0003דהוה\u0004 \u0005[שהיה]\u0006 \u0003בן עשרים\u0004 כשהגיע לארץ, ולכן קיבל נחלה בזכות עצמו. \u0003הא\u0004 \u0005[זו]\u0006 שנויה במי ש\u0003לא הוה\u0004 \u0005[היה]\u0006 \u0003בן עשרים,\u0004 ולכן נתנו לו נחלה בזכות אבי אביו או אבי אימו.","שנינו במשנה: \u0003ושהיה\u0004 צלפחד \u0003בכור נוטל שני חלקים.\u0004 ומקשים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 לצלפחד היה חלק בכורה? הלא חלקו בירושת ארץ ישראל \u0003ראוי הוא,\u0004 שירושה זו של הארץ לא הגיעה ממש לידיו של חפר, \u0003ו\u0004כלל הוא ש\u0003אין הבכור נוטל בראוי כבמוחזק!\u0004 \u0003אמר רב יהודה אמר שמואל:\u0004 הכוונה אינה שנטלו חלק בכורה בארץ, אלא \u0003ביתדות אהלים,\u0004 כלומר, בכל מיני מיטלטלים שהביאו איתם במדבר, ואותם ירשו יורשי חפר, ומהם קיבלו חלק בכורה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רבה\u0004 ממה ששנינו, \u0003ר' יהודה אומר: בנות צלפחד נטלו ארבעה חלקים, שנאמר \"ויפלו חבלי מנשה עשרה\"\u0004 (יהושע יז, ה), וברור מן הענין שמדובר שקיבלו נחלה ממש בארץ, ולא רק מיטלטלים! \u0003אלא אמר רבה: ארץ ישראל\u0004 אינה נחשבת רק ראויה ליוצאי מצרים, אלא \u0003מוחזקת היא\u0004 להם, אף שלא נכנסו לתוכה, ולכן יש בה דין בכורה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו במדרש ההלכה, \u0003אמר\u0004 \u0003ר' חידקא: שמעון השקמוני היה לי חבר\u0004 שהיה \u0003מתלמידי\u0004 \u0003ר' עקיבא, וכך היה\u0004 \u0003ר' שמעון השקמוני אומר: יודע היה משה רבינו שבנות צלפחד יורשות הן\u0004 את נחלת אביהן, ואת חלקו בנחלת חפר ככל אחיו, ולא על כך הוצרך לשאול מאת ה', \u0003אבל לא היה יודע אם\u0004 הן \u0003נוטלות חלק בכורה\u0004 בנכסי חפר \u0003אם לאו\u0004 \u0005[לא].\u0006","ועוד אמר: \u0003וראויה היתה פרשת נחלות ליכתב על ידי משה\u0004 עצמו, כשאר הלכות שבתורה, אף אם לא היו באות אליו בנות צלפחד ושואלות אותו על נחלתן, \u0003אלא שזכו בנות צלפחד ונכתבה על ידן,\u0004 על ידי שאלתן.","וכיוצא בזה בהלכה אחרת שנכתבה בתורה באופן דומה, כשמצאו בני ישראל איש מקושש עצים ביום השבת, ואז נאמרה ההלכה הנוגעת לאותו ענין, שדינו למות בסקילה (ראה במדבר טו, לב–לו), \u0003ויודע היה משה רבינו ש\u0004דינו של \u0003המקושש\u0004 עצים בשבת הוא \u0003במיתה, שנאמר\u0004 לגבי שבת: \u0003\"מחלליה מות יומת\"\u0004 (שמות לא, יד), \u0003אבל לא היה יודע באי זו מיתה הוא ימות. וראויה היתה פרשת מקושש שתכתב על ידי משה\u0004 גם בלא אותו מעשה, לדעת מהו עונשו של מחלל שבת, \u0003אלא שנתחייב מקושש\u0004 ועבר עבירה \u0003ונכתבה\u0004 פרשת עונשו של מחלל השבת \u0003על ידו; ללמדך,\u0004"],["\u0003שמגלגלים זכות על ידי זכאי וחובה על ידי חייב,\u0004 ולפיכך, בנות צלפחד שהיו זכאיות — זכו שתתגלה בגללן פרשה של זכות, והמקושש — פרשה של חובה. אלו דברי ר' שמעון השקמוני.","\u0003ו\u0004מעתה, \u0003אי סלקא דעתך\u0004 \u0005[אם עולה\u0006 על \u0005דעתך]\u0006 לומר כדברי רבה ש\u0003ארץ ישראל מוחזקת\u0004 היא, \u0003מאי קא מסתפקא ליה\u0004 \u0005[מה היה מסופק לו]\u0006 למשה רבינו אם בנות צלפחד נוטלות חלק בכורה? והלא נחלת חפר נחשבה כמוחזקת, וצלפחד היה בכורו!","ומשיבים: \u0003היא גופה\u0004 \u0005[עצמה]\u0006 השאלה האם ארץ ישראל מוחזקת בידי יוצאי מצרים, \u0003קא מסתפקא ליה\u0004 \u0005[היתה מסופקת לו],\u0006 והיא היתה השאלה ששאל את ה', וכך נסתפק: האם מה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ונתתי אתה לכם מורשה אני ה'\"\u0004 (שמות ו, ח), כוונתו לומר: ארץ ישראל \u0003ירושה היא לכם מאבותיכם,\u0004 ודינה כמוחזקת בידי יוצאי מצרים, \u0003או דלמא\u0004 \u0005[שמא]\u0006 כוונת השימוש במלה \"מורשה\" באה להדגיש להם ענין אחר, לומר ליוצאי מצרים \u0003ש\u0004הם \u0003מורישין\u0004 לבניהם את הנחלה, \u0003ואינן יורשין\u0004 בעצמם, לפי שהם עתידים למות במדבר?","\u0003ופשטו ליה\u0004 \u0005[ופתרו לו]\u0006 מן השמים \u0003תרוייהו\u0004 \u0005[שתיהן]:\u0006 שהפסוק בא ללמד כי \u0003ירושה לכם מאבותיכם\u0004 שהארץ מוחזקת ויש בה חלק בכורה, \u0003ו\u0004גם ש\u0003מורישין ואינן יורשין. ו\u0004דבר זה שכבר מראש נאמר ליוצאי מצרים שאינם עתידים להיכנס לארץ, \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 כשאמרו ישראל בשירת הים: \u0003\"תביאמו ותטעמו בהר נחלתך\"\u0004 (שמות טו, יז), ויש לדייק בכתוב: \u0003תביאנו\u0004 (=תביא אותנו) \u0003לא נאמר, אלא \"תביאמו\"\u0004 (=תביא אותם), \u0003מלמד ש\u0004היו בני ישראל \u0003מתנבאין\u0004 באותה עת שהם עצמם לא יגיעו לארץ, \u0003ואינן יודעין מה\u0004 הם \u0003מתנבאין.\u0004","אגב שהובא מעשה בנות צלפחד, דנים עוד בפרשה זו, נאמר: \u0003\"ותעמדנה לפני משה ולפני אלעזר הכהן ולפני הנשיאים וכל העדה\"\u0004 (במדבר כז, ב), ויש לתמוה על סדר הפסוק: \u0003אפשר עמדו\u0004 לדין בתחילה \u0003לפני משה,\u0004 ולא אמר להם דבר, ואחר כך באו לפני אלעזר, \u0003ולא אמרו להן דבר, ועמדו לפני הנשיאים וכל העדה\u0004 ושאלו אותם?","\u0003אלא סרס המקרא\u0004 קרא אותו שלא כסדרו \u0003ודרשהו,\u0004 שתחילה הלכו לעדה וגמרו במשה רבינו, אלו \u0003דברי\u0004 \u0003ר' יאשיה.\u0004 \u0003אבא חנן אמר משום\u0004 (בשם) \u0003ר' אליעזר: בבית המדרש היו\u0004 כולם \u0003יושבין,\u0004 משה ואליעזר, הנשיאים והעם, \u0003והלכו\u0004 בנות צלפחד \u0003ועמדו להן\u0004 באותה שעה \u0003לפני כולן,\u0004 והכתוב מונה אותם לפי סדר חשיבותם.","ומעירים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חלוקים]\u0006 שפירשו את המקרא הזה בצורות שונות? \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 אבא חנן, \u0005סבור]:\u0006 \u0003חולקין כבוד לתלמיד במקום הרב,\u0004 ולכן מזכירים גם את התלמיד במקום שהרב נמצא בו. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יאשיה, \u0005סבור]:\u0006 \u0003אין חולקין\u0004 כבוד לתלמיד במקומו של הרב, ואם היו כולם יושבים יחד לא היו מזכירים את האחרים במקום משה.","ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]\u0006 ש\u0003חולקין\u0004 כבוד לתלמיד. \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]\u0006 ש\u0003אין חולקין.\u0004 ותוהים: \u0003קשיא הלכתא אהלכתא\u0004 \u0005[קשה הלכה על הלכה]!\u0006 ומשיבים: \u0003הלכתא אהלכתא\u0004 \u0005[מהלכה על הלכה]\u0006 \u0003לא קשיא\u0004 \u0005[קשה],\u0006 כי מדובר במקרים שונים, \u0003הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 שחולקים כבוד לתלמיד מדברת באופן \u0003דפליג ליה רביה יקרא\u0004 \u0005[שחולק לו רבו\u0006 עצמו \u0005כבוד]\u0006 ואז מותר גם לאחרים לחלוק לו כבוד, \u0003הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 שאין חולקים כבוד לתלמיד מדברת באופן ש\u0003לא פליג ליה רביה יקרא\u0004 \u0005[חולק לו רבו כבוד],\u0006 ואז אין אחר רשאי לעשות זאת.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003בנות צלפחד חכמניות הן, דרשניות הן, צדקניות הן.\u0004","ומסבירים: מנין ש\u0003חכמניות הן\u0004 — \u0003שלפי שעה דברו,\u0004 כלומר, שבאו בטענתן בזמן הנכון, בעת שראויה טענתן להישמע. ש\u0003אמר רב שמואל בר רב יצחק: מלמד שהיה משה רבינו יושב ודורש\u0004 באותו הזמן \u0003בפרשת יבמין, שנאמר: \"כי ישבו אחים יחדו\u0004 ומת אחד מהם ובן אין לו... יבמה יבוא עליה ולקחה לו לאשה\u0003\"\u0004 (דברים כה, ה), באותה שעה \u0003אמרו לו\u0004 בנות צלפחד: לפי זה, \u0003אם כבן אנו חשובין\u0004 — \u0003תנה לנו נחלה כבן, אם לאו\u0004 \u0005[לא]\u0006 — \u0003תתיבם אמנו! מיד\u0004 כששמע משה את הדברים הללו, שהיה טעם בדבריהן, \u0003\"ויקרב משה את משפטן לפני ה'\"\u0004 (במדבר כז, ה).","ומנין ש\u0003דרשניות הן\u0004 — \u0003שהיו\u0004 יודעות לדרוש את הכתוב ו\u0003אומרות: אילו היה לו בן לא דברנו,\u0004 אבל כיון שאין בן — הרי אנו עומדות במקומו. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 אילו היתה לו \u0003בת\u0004 לא דיברנו! \u0003אמר\u0004 \u0003ר' ירמיה: סמי\u0004 \u0005[מחק]\u0006 \u0003מכאן \"בת\",\u0004 כלומר, לא כך צריך לומר, שהרי הן עצמן היו בנות. \u0003אביי אמר,\u0004 כך צריך לפרש: \u0003אפילו היה בת לבן לא דברנו,\u0004 שהיא היתה זוכה בנחלה. אבל כיון שלא נשארו צאצאים אחרים, הנחלה היא לנו.","ומנין ש\u0003צדקניות הן\u0004 — \u0003שלא נישאו,\u0004 כלומר, מיהרו להינשא, \u0003אלא\u0004 המתינו עד שיינשאו \u0003להגון\u0004 (מתאים) \u0003להן.\u0004 \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' אליעזר בן יעקב: אפילו קטנה\u0004 (צעירה) \u0003שבהן לא נשאת\u0004 כשהיתה \u0003פחותה מארבעים שנה,\u0004 שכל כך המתינו עד שיימצא הבעל הראוי להן.","ומקשים: \u0003איני\u0004 \u0005[כן הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב חסדא:\u0004 מי ש\u0003ניסת פחותה מבת עשרים\u0004 שנה — הרי היא \u0003יולדת\u0004 ילדים \u0003עד\u0004 גיל \u0003ששים\u0004 שנה, אם נישאת מ\u0003בת עשרים\u0004 ומעלה — \u0003יולדת עד\u0004 גיל \u0003ארבעים,\u0004 אם נישאת \u0003בת ארבעים\u0004 — \u0003שוב אינה יולדת\u0004 לעולם! \u0003אלא, מתוך שצדקניות הן נעשה להן נס כיוכבד,\u0004 שילדו הרבה לאחר הזמן הראוי לשאר נשים ללדת. ומהו הנס שנעשה ביוכבד? — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 כשלקח עמרם את יוכבד קודם שנולד משה: \u0003\"וילך איש מבית לוי ויקח את בת לוי\"\u0004 (שמות ב, א),"],["\u0003אפשר\u0004 שמי שהיא \u0003בת מאה ושלשים שנה וקרא לה\u0004 הכתוב \"\u0003בת\",\u0004 שמשמעו — צעירה מאד? ומנין שבת מאה ושלושים שנה היתה יוכבד באותו הזמן — שכן במנין בני לאה היורדים למצרים נאמר ככלל שהיו שלושים ושלושה, ובמנין בפועל מנויים שלושים ושנים, הרי חסר אחד מן המנין שלא נתפרש שמו, ובהסבר הדבר \u0003אמר\u0004 \u0003ר' חמא בר חנינא: זו יוכבד שהורתה\u0004 (הריונה) היה \u0003בדרך\u0004 למצרים \u0003ונולדה בין החומות,\u0004 כלומר, בתוך מצרים עצמה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ושם אשת עמרם יוכבד בת לוי \u0003אשר ילדה אתה ללוי במצרים\"\u0004 (במדבר כו, נט), ותוספת זו באה לומר כי","\u0003לידתה\u0004 היתה \u0003במצרים,\u0004 אבל \u0003הורתה\u0004 היתה \u0003שלא\u0004 \u0003במצרים.\u0004 ומכיון שבמצרים נשתעבדו מאתים ועשר שנים ומשה בנה היה ביציאת מצרים בן שמונים שנה, הרי שבלידתה אותה היתה בת מאה ושלושים שנה, וקודם לכן, באותה שנה נלקחה על ידי עמרם לאשה, \u0003אם כן אמאי\u0004 \u0005[מדוע]\u0006 \u0003קרו\u0004 \u0005[קוראים]\u0006 \u0003לה \"בת\"\u0004 כשלקח אותה עמרם? \u0003אמר רב יהודה בר זבידא: מלמד שנולדו בה\u0004 אז מחדש \u0003סימני נערות,\u0004 \u0003נתעדן הבשר, נתפשטו\u0004 (נתיישרו) \u0003הקמטין, וחזר היופי למקומו.\u0004","ועוד שואלים באותו ענין, שנאמר בו: \u0003\"ויקח\u0004 את בת לוי \u0003\",\u0004 והלא \u0003\"ויחזור\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 שהרי נשואה היתה לעמרם קודם לכן, והיו לו כבר ילדים (מרים ואהרן) ממנה! \u0003אמר רב יהודה בר זבידא: מלמד שעשה לה\u0004 אז \u0003מעשה לקוחין\u0004 (נישואין) כאילו הוא נושא אשה חדשה, \u0003הושיבה באפריון\u0004 (כמו שעושים לכלה), \u0003ואהרן ומרים\u0004 ילדיה היו \u0003משוררים לפניה, ומלאכי שרת אומרים: \"אם הבנים שמחה\"\u0004 (תהלים קיג, ט).","ועוד בענין בנות צלפחד, שרשימת שמותיהן מופיעה פעמיים בתורה, ובסדר שונה, מעירים: \u0003להלן\u0004 בזמן נישואיהן \u0003מנאן הכתוב דרך גדולתן\u0004 בשנים (\"ותהיינה מחלה תרצה וחגלה ומלכה ונעה בנות צלפחד לבני דודיהן לנשים\". במדבר לו, יא), \u0003וכאן\u0004 כשבאו לפני משה, מנאן \u0003דרך חכמתן,\u0004 ככתוב \"ואלה שמות בנותיו מחלה נעה וחגלה ומלכה ותרצה\" (במדבר כז, א). ומוסיפים: \u0003מסייעא ליה\u0004 \u0005[מסייע לו\u0006 הדבר\u0005]\u0006 \u0003לר' אמי,\u0004 ש\u0003אמר\u0004 \u0003ר' אמי: בישיבה,\u0004 במקום שיושבים בדין תורה או בלימוד תורה, \u0003הלך\u0004 (לך) בסדר הישיבה, לפי החשיבות, \u0003אחר חכמה,\u0004 והחכם שבהם קודם. \u0003במסיבה\u0004 כשמסבים לסעודה, \u0003הלך\u0004 בסדר הישיבה \u0003אחר זקנה. אמר רב אשי: והוא דמפליג\u0004 \u0005[שמופלג,\u0006 גדול במיוחד\u0005]\u0006 האיש \u0003בחכמה,\u0004 אז מקדימים אותו בישיבה למי שזקן ממנו. וכן להיפך, \u0003והוא דמפליג\u0004 \u0005[שמופלג]\u0006 \u0003בזקנה\u0004 אז מקדימים אותו במסיבה למי שחכם ממנו.","ומעירים: שלא כמו האמור לעיל, \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: בנות צלפחד שקולות היו\u0004 זו כנגד זו, \u0003שנאמר: \"ותהיינה\u0004 מחלה תרצה וחגלה ומלכה ונעה בנות צלפחד לבני דודיהן לנשים\", \u0003הויה\u0004 (מהות) \u0003אחת לכולן\u0004 שכולן נבונות כאחת.","ודנים בענין נישואיהן של בנות צלפחד, \u0003אמר רב יהודה אמר שמואל: בנות צלפחד הותרו להנשא לכל השבטים\u0004 ולאו דווקא לבני שבטן, \u0003שנאמר: \"לטוב בעיניהם תהיינה לנשים\"\u0004 (במדבר כז, ו), \u0003אלא מה אני מקיים \"אך למשפחת מטה אביהם תהיינה לנשים\"\u0004 (במדבר כז, ו)? — \u0003עצה טובה השיאן הכתוב, שלא ינשאו אלא להגון להן,\u0004 והראוי להן ביותר הוא בן משפחתן.","\u0003מותיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רבה\u0004 ממה ששנינו: מה שנאמר בענין איסור אכילת קדשים בטומאה: \u0003\"אמר אליהם\"\u0004 (ויקרא כב, ג), כוונתו \u0003לאותן העומדים על הר סיני\u0004 שאליהם נאמר הדיבור, \u0003\"לדרתיכם\"\u0004 (ויקרא כב, ג) — \u0003אלו דורות הבאים.\u0004 ויש לשאול: \u0003אם נאמר\u0004 הציווי ל\u0003אבות, למה נאמר\u0004 ל\u0003בנים, ואם נאמר\u0004 ל\u0003בנים, למה נאמר\u0004 ל\u0003אבות?\u0004 אלא יש ליישב את הדבר ולומר: \u0003מפני שיש באבות\u0004 מצוות \u0003מה שאין בבנים, ויש בבנים מה שאין באבות.\u0004","\u0003באבות הוא אומר: \"וכל בת ירשת נחלה. . .\u0004 לאחד ממשפחת מטה אביה תהיה לאשה\u0003\"\u0004 (במדבר כז, ח), ומצוה זו שתינשא האשה לבן שבטה היתה רק בדור האבות, בדור נוחלי הארץ, ולא בדורות לאחר מכן, \u0003ו\u0004מצד אחר \u0003הרבה מצו‍ת נצטוו בנים שלא נצטוו אבות,\u0004 והן כל המצוות התלויות בביאה לארץ ובישיבה בה. \u0003הא\u0004 \u0005[הרי]\u0006 לפי זה \u0003מפני שיש באבות\u0004 דברים \u0003שאין בבנים, ויש בבנים מה שאין באבות\u0004 — \u0003הוצרך לומר אבות, הוצרך לומר בנים.\u0004 עד כאן דברי הברייתא.","ולענייננו, \u0003קתני מיהת\u0004 \u0005[שנה על כל פנים]:\u0006 \u0003באבות הוא אומר: \"וכל בת ירשת נחלה\",\u0004 משמע שמצוה זו להינשא לבן השבט היתה קיימת בכל בנות אותו הדור, ואף בנות צלפחד בכלל, שלא כדברי רב יהודה בשם שמואל! \u0003הוא\u0004 רבה \u0003מותיב לה\u0004 \u0005[היה מקשה אותה\u0006 את הקושיה הזו\u0005],\u0006 \u0003והוא\u0004 עצמו \u0003מפרק לה\u0004 \u0005[היה מתרץ אותה]:\u0006 \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מבנות צלפחד,\u0004 שלהן נאמר במיוחד שהן יכולות להינשא למי שהן רוצות. ודנים בדברי הברייתא.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003באבות הוא אומר \"וכל בת ירשת נחלה\",\u0004 ומשמעות הדברים: \u0003באבות\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 קיים דין זה, \u0003בבנים\u0004 — \u0003לא.\u0004 ושואלים: \u0003מאי משמע\u0004 \u0005[כיצד נשמע\u0006 דבר זה מן המקרא\u0005]?\u0006 \u0003אמר רבא, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"זה הדבר\"\u0004 (במדבר כז, ו), \u0003דבר זה לא יהא נוהג אלא בדור זה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה זוטי\u0004 \u0005[הקטן]\u0006 \u0003לרב אשי: אלא מעתה,\u0004 שכך אתה דורש את \"זה הדבר\", אם כן \u0003\"זה הדבר\"\u0004 שכתוב ב\u0003שחוטי חוץ\u0004 (\"איש איש מבית ישראל אשר ישחט שור או כשב או עז במחנה או אשר ישחט מחוץ למחנה...\". ויקרא יז, ג), שנאסר לשחוט קרבן מחוץ למשכן, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003לא יהא נוהג אלא בדור זה?\u0004 והרי אין מי שסבור כן! ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004חוקת עולם תהיה זאת להם \u0003לדרתם\"\u0004 (ויקרא יז, ז), לומר שמצוה זו קיימת לכל הדורות."],["שאל אותו עוד: פרשת נדרים והפרתם, שנאמר בה \u0003\"זה הדבר\"\u0004 ל\u0003ראשי המטות,\u0004 ככתוב \"וידבר משה אל ראשי המטות לבני ישראל לאמר זה הדבר אשר צוה ה', איש כי ידור נדר לה'. . . \" (במדבר ל, ב–יז), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003לא יהא נוהג\u0004 דין זה \u0003אלא בדור זה\u0004 בלבד?! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003ההוא יליף\u0004 \u0005[אותו\u0006 ענין, פרשת נדרים, \u0005למד]\u0006 בגזירה שווה \u0003\"זה\" \"זה\" מהתם\u0004 \u0005[משם]\u0006 מפרשת שחוטי חוץ, שאף היא נוהגת לדורות.","ומקשים: \u0003האי נמי ליליף\u0004 \u0005[זה גם כן,\u0006 דין בת יורשת, \u0005שילמד]\u0006 \u0003\"זה\" \"זה\" מהתם\u0004 \u0005[משם]\u0006 משחוטי חוץ! ודוחים: \u0003האי מאי\u0004 \u0005[\u0006דבר \u0005זה מה\u0006 עניינו\u0005]?\u0006 \u0003בשלמא התם איצטריך\u0004 \u0005[נניח שם,\u0006 בשחוטי חוץ ובנדרים, \u0005הוצרך]\u0006 הביטוי \"זה הדבר\" \u0003לגזרה שוה\u0004 לענין אחר, כמבואר להלן, ומשום כך למדים גזירה שווה גם לענין זה, אבל \u0003הכא למאי איצטריך\u0004 \u0005[כאן,\u0006 בענין בת יורשת נחלה, \u0005למה הוצרך]?\u0006 ואם רק כדי לומר שהוא לדורות — \u0003לשתוק קרא מיניה, ואנא ידענא\u0004 \u0005[שישתוק הכתוב ממנו,\u0006 ולא יאמר \"זה הדבר\", \u0005ואני יודע]\u0006 ש\u0003לדורות הוא,\u0004 כמו שכל דבר הכתוב בתורה הריהו לדורות.","ומבארים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 אותה \u0003גזרה שוה\u0004 שהוזכרה? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נאמר כאן\u0004 בפרשת נדרים \u0003\"זה הדבר\"\u0004 (במדבר ל, ב), \u0003ונאמר להלן\u0004 בפרשת שחוטי חוץ \u0003\"זה הדבר\"\u0004 (ויקרא יז, ב), \u0003מה להלן\u0004 בציווי שחוטי חוץ, נכללים \u0003אהרן ובניו וכל ישראל,\u0004 כאמור שם: \"דבר אל אהרן ואל בניו ואל כל בני ישראל\" — \u0003אף כאן\u0004 בנדרים ובהפרתם, נכללים \u0003אהרן ובניו וכל ישראל; ומה כאן\u0004 בפרשת נדרים, מדובר ב\u0003ראשי המטות\u0004 ככתוב \"וידבר משה אל ראשי המטות לבני ישראל. . . \"— \u0003אף להלן\u0004 בשחוטי חוץ, יש ענין ב\u0003ראשי המטות.\u0004","ודנים עתה בברייתא זו לגופה: \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003מה להלן אהרן ובניו וכל ישראל, אף כאן אהרן ובניו וכל ישראל.\u0004 ושואלים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 בא הדבר? \u0003אמר רב אחא בר יעקב: לומר, שהפרת נדרים\u0004 נעשית אף \u0003בשלשה הדיוטות,\u0004 כלומר, בכל אדם מישראל, כמו שדין שחיטת חוץ נאמר לכל אדם מישראל.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 בדין נדרים \u0003\"ראשי המטות\" כתיב ביה\u0004 \u0005[נאמר בו]\u0006 במפורש, ואיך אתה יכול לומר שהוא נוהג בכל ישראל? ומשיבים: \u0003כ\u0004ענין ש\u0003אמר רב חסדא אמר\u0004 \u0003ר' יוחנן\u0004 בתשובה לשאלה דומה, שמביטוי זה למדנו אפשרות להתיר נדרים \u0003ביחיד מומחה,\u0004 אם כן, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 אפשר לתרץ שביטוי זה בא ללמד על התרת נדרים שנעשית גם \u0003ביחיד מומחה.\u0004","ועל מה ששנינו עוד בברייתא: \u0003ומה כאן ראשי המטות, אף להלן ראשי המטות.\u0004 שואלים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 בא הדבר? מה שייך ענין ראשי המטות לגבי שחוטי חוץ? \u0003אמר רב ששת: לומר, שיש שאלה בהקדש,\u0004 כלומר, שגם בהקדש, כמו בשאר נדרים, יכול המקדיש להישאל על ידי חכם שיברר האם כשהקדיש ידע אז את כל משמעות הנדר, ואם ימצא לו החכם מקום להתיר — הנדר בטל למפרע, וההקדש לא חל מעיקרו.","ושואלים: \u0003ול\u0004דעת \u0003בית שמאי דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003אין שאלה בהקדש, דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 \u0003בית שמאי אומרים: הקדש טעות\u0004 — \u0003הקדש,\u0004 שאף שידוע לנו שאדם לא התכוון למה שהוציא מפיו — הרי זה הקדש, שאין הולכים אחר דעתו, \u0003ובית הלל אומרים: אינו הקדש,\u0004 ונמצא שלדעת בית שמאי אין דורשים גזירה שווה זו, אם כן \u0003האי\u0004 \u0005[זה,\u0006 הביטוי\u0005]\u0006 \u0003\"זה\" ו\"זה\"\u0004 האמור בפרשת שחוטי חוץ ובפרשת נדרים \u0003מאי עבדי ליה\u0004 \u0005[מה עושים\u0006 הם \u0005בו]?\u0006","ומשיבים: \u0003\"זה הדבר\"\u0004 ב\u0003שחוטי חוץ מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 ללמד מיעוט: \u0003על השוחט\u0004 (השחיטה) \u0003הוא חייב,\u0004 כלומר, דווקא על מעשה שחיטה של קרבן המפורש בכתוב \"איש . . . אשר ישחט\" (ויקרא יז, ג) חייבים בחוץ, \u0003ואינו חייב על המולק\u0004 (המליקה), שהמולק עוף של קרבן בחוץ, אם עשה כן בחוץ — אינו בגדר שוחט בחוץ החייב כרת; \u0003\"זה הדבר\"\u0004 ב\u0003\"ראשי המטות\" מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 גם כן למיעוט, \u0003ל\u0004למד: \u0003חכם מתיר ואין בעל מתיר,\u0004 שהחכם יכול להתיר את הנדר, כששואל את הנודר ומוצא לו פתח או חרטה. אבל בעל אינו יכול להתיר נדרי אשתו באופן זה, אלא רק לבטלם (ואף זה — רק בו ביום ששמע את הנדר). ולהיפך, \u0003בעל מפר\u0004 את הנדר לאשתו או בתו בו ביום ששמע את נדר אשתו, מבלי שהדבר יהא תלוי בדעתה כלל, \u0003ואין חכם מפר,\u0004 שאינו מתיר את הנדר אלא בדרך של שאלה.","ושואלים: \u0003ול\u0004דעת \u0003בית שמאי דלית להו\u0004 \u0005[שאין להם,\u0006 שאינם מקבלים\u0005]\u0006 \u0003גזרה שוה\u0004 זו, \u0003הפרת נדרים\u0004 שיכולה להיעשות אף \u0003בשלשה הדיוטות מנא להו\u0004 \u0005[מנין להם]?\u0006 ומשיבים: \u0003נפקא להו מדתניא\u0004 \u0005[יוצא להם\u0006 הדבר \u0005ממה ששנינו\u0006 בברייתא\u0005]:\u0006 נאמר בסוף פרשת המועדות שבפרשת אמור: \u0003\"וידבר משה את מעדי ה' אל בני ישראל\"\u0004 (ויקרא כג, מד), \u0003ר' יוסי הגלילי אומר:\u0004"],["\u0003מועדי ה' נאמרו, שבת בראשית,\u0004 כלומר, שבת שבכל יום שביעי בשבוע, מאז ימי בראשית, \u0003לא נאמרה; בן עזאי אומר: מועדי ה' נאמרו, הפרת נדרים לא נאמרה.\u0004","מסופר: \u0003ר' יוסי בר נתן גמיר לה להא מתניתא\u0004 \u0005[שנה את הברייתא הזו]\u0006 \u0003ולא ידע ליה לפרושה\u0004 \u0005[\u0006היה \u0005יודע לפרש אותה].\u0006 \u0003אזל בתריה\u0004 \u0005[הלך אחרי]\u0006 \u0003רב ששת לנהרדעא\u0004 כדי לשאול אותו מה פירושה, \u0003ולא אשכחיה\u0004 \u0005[מצאו]\u0006 שם. \u0003אזל בתריה\u0004 \u0005[הלך אחריו]\u0006 \u0003למחוזא\u0004 ושם \u0003אשכחיה\u0004 \u0005[מצאו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 דברי ר' יוסי הגלילי שבברייתא \u0003\"מועדי ה' נאמרו, שבת בראשית,\u0004 כלומר, שבת שבכל יום שביעי בשבוע, מאז ימי בראשית, \u0003לא נאמרה\"?\u0004 והרי ודאי נאמרה גם שבת בראשית בפרשה זו!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 הכוונה היא ש\u0003מועדי ה' צריכין קידוש בית דין,\u0004 שאין המועדים נקבעים מעצמם, אלא רק לאחר שבית הדין קידש את ראש החודש נקבעים ומתקדשים גם המועדים החלים באותו חודש, לפי התאריך הכתוב בתורה. אבל \u0003שבת בראשית אינה צריכה קידוש בית דין,\u0004 אלא קדושתה חלה מעצמה בכל יום שביעי. שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכתיבי גבי\u0004 \u0005[ונאמרה\u0006 שבת בראשית \u0005אצל]\u0006 כל ה\u0003מועדות,\u0004 באותה פרשה המדברת ב\"מועדי ה'\" (ויקרא פרק כג), \u0003תיבעי\u0004 \u0005[תצטרך]\u0006 אף היא \u0003קידוש בית דין כמועדות,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא.","ועוד שאל ר' יוסי בר נתן את רב ששת: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 דברי בן עזאי שבברייתא \u0003\"מועדי ה' נאמרו, הפרת נדרים לא נאמרה\"?\u0004 והרי הפרת נדרים נאמרה במפורש! אמר לו: הכוונה היא \u0003מועדי ה' צריכין מומחין\u0004 כדי שיקבעו אותם, שאין קביעת המועדים נעשית אלא על ידי דיינים מומחים, ואילו \u0003הפרת נדרים אינה צריכה מומחין.\u0004 ומכאן בית שמאי למדים כי הפרת נדרים נעשית בשלושה הדיוטות.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"ראשי המטות\" כתיב\u0004 \u0005[נאמר\u0006 בפרשת נדרים\u0005]?\u0006 משמע שצריך בזה דווקא חכמים מומחים! \u0003אמר רב חסדא אמר\u0004 \u0003ר' יוחנן:\u0004 מה שהוזכרו שם \"ראשי המטות\" הכוונה היא ללמדנו שהתרת נדרים יכולה להיעשות גם \u0003ביחיד מומחה,\u0004 שהוא רשאי להתיר לבדו.","כיון שדברנו עד כה בהלכות בת יורשת נחלה, שלא הותר לה להינשא בזמן הכניסה לארץ לאדם משבט אחר, מביאים: \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה במסכת תענית\u0005],\u0006 \u0003אמר רבן שמעון בן גמליאל: לא היו ימים טובים לישראל כחמשה עשר באב וכיום הכפורים, שבהן\u0004 כל \u0003בנות ירושלים\u0004 היו \u0003יוצאות בכלי\u0004 (בגדי) \u0003לבן שאולין,\u0004 ומדוע כולן שאלו בגדים, ואף מי שיש לה? כדי \u0003שלא לבייש את מי שאין לו\u0004 בגדים, ובושה היא לשאול. ודנים בכך: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003יום הכפורים\u0004 הינו יום טוב ועושים בו שמחה, משום ש\u0003יום סליחה ומחילה\u0004 הוא, \u0003יום שנתנו בו לוחות אחרונות\u0004 לאחר שנשברו הראשונות בחטא העגל, \u0003אלא חמשה עשר באב מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 הסיבה לחגיגיותו?","\u0003אמר רב יהודה אמר שמואל:\u0004 משום שהוא \u0003יום ש\u0004בו \u0003הותרו שבטים לבא\u0004 (להינשא) \u0003זה בזה,\u0004 שהרי כאמור לעיל, אסור היה לבת יורשת נחלה להינשא לבן שבט אחר, וממילא צימצם הדבר את הנישואין בין השבטים, ומשעה שכלה דור הנכנסים לארץ, התירו לבנות כאלה להינשא לבן שבט אחר. ושואלים: \u0003מאי דרוש\u0004 \u0005[מה דרשו]?\u0006 על איזה כתוב הסתמכו להתיר איסור זה? — שנאמר באותו איסור מתחילתו: \u0003\"זה הדבר\"\u0004 (במדבר לו, ו), לומר: \u0003דבר זה לא יהא נוהג אלא בדור זה\u0004 של חלוקת הארץ.","\u0003רבה בר בר חנה אמר\u0004 בשם \u0003ר' יוחנן:\u0004 השמחה המיוחדת של ט\"ו באב היא משום שהוא \u0003יום ש\u0004בו \u0003הותר שבט בנימן לבא בקהל, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בעקבות פרשת פילגש בגבעה ומלחמת עם ישראל בשבט בנימין: \u0003\"ואיש ישראל נשבע במצפה לאמר איש ממנו לא יתן בתו לבנימן לאשה\"\u0004 (שופטים כא, א), ולכן לא יכלו להשיא נשים לבני בנימין. \u0003מאי דרוש\u0004 \u0005[מה דרשו]\u0006 כדי להתיר להם שבועה זו? שאמרו שנשבעו \"איש \u0003ממנו\u0004 (מאיתנו) לא יתן בתו\" ויש לדייק: \u0003ולא מבנינו.\u0004","\u0003רב דימי בר יוסף אמר\u0004 בשם \u0003רב נחמן\u0004 טעם אחר: יום ט\"ו באב הוא \u0003יום שכלו בו מתי מדבר,\u0004 שפסקו למות יוצאי מצרים שנידונו למות במדבר בעקבות חטא המרגלים, ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003עד שלא כלו מתי מדבר\u0004"],["\u0003לא היה דיבור\u0004 מפי ה' \u0003עם משה, שנאמר: \"ויהי כאשר תמו כל אנשי המלחמה למות מקרב העם\"\u0004 (דברים ב, טז), \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 נאמר: \u0003\"וידבר ה' אלי לאמר\"\u0004 (דברים ב, יז), לומר: אז \u0003אלי היה הדיבור.\u0004","\u0003עולא אמר\u0004 טעם אחר: ט\"ו באב הוא יום שמחה משום שהוא \u0003יום שביטל בו הושע בן אלה\u0004 מלך ישראל \u0003פרדסאות\u0004 (משמרות) \u0003שהושיב ירבעם\u0004 בן נבט \u0003על הדרכים\u0004 כדי \u0003שלא יעלו ישראל לרגל\u0004 לירושלים. שהושע ביטל את הדבר והתאפשר לאנשים לעלות.","\u0003רב מתנה אמר\u0004 טעם אחר: ט\"ו באב הוא \u0003יום שנתנו\u0004 בו \u0003הרוגי ביתר לקבורה,\u0004 שגזר עליהם אדריינוס שלא יקברו. וכפי ש\u0003אמר רב מתנה: אותו היום שנתנו הרוגי ביתר לקבורה\u0004 — \u0003תקנו ביבנה\u0004 להוסיף בברכת המזון את ברכת \u0003\"הטוב והמטיב\",\u0004 ומדוע אומרים אותה בלשון זו לזכר אותו אירוע? \u0003\"הטוב\"\u0004 — \u0003שלא הסריחו\u0004 הגופות, למרות שחלף זמן רב, \u0003\"והמטיב\"\u0004 — \u0003שנתנו לקבורה.\u0004","\u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 הטעם שמציינים את היום הזה הוא משום שהוא \u0003יום שפוסקין בו מלכרות עצים למערכה\u0004 של המזבח. ובטעמו של דבר \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר הגדול אומר: כיון שהגיע חמשה עשר באב תשש כחה של חמה,\u0004 שוב אין החמה מחממת כל כך, \u0003ו\u0004לכן \u0003לא היו כורתין\u0004 עוד \u0003עצים למערכה,\u0004 משום שהם אינם יבשים כל צרכם. \u0003אמר רב מנשה: וקרו ליה\u0004 \u0005[וקוראים לו]\u0006 ליום הזה \u0003\"יום תבר\u0004 \u0005[שבירת]\u0006 \u0003מגל\",\u0004 ששוב אין נזקקים לכלי הקצירה.","\u0003מכאן ואילך,\u0004 ה\u0003מוסיף\u0004 בלימודו, בלילות המתארכים באותה תקופה — \u0003יוסיף\u0004 חיים, ו\u0003שאינו מוסיף\u0004 — \u0003יסיף.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"יסיף\"? תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף: תקבריה אמיה\u0004 \u0005[תקברנו אימו],\u0006 כלומר, ייאסף מן העולם בחיי אמו.","כיון שנזכר ענין מות דור המדבר בעקבות חטא המרגלים, מביאי את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003שבעה\u0004 אנשים \u0003קפלו את כל העולם כולו\u0004 כלומר, ימי חייהם כוללים את כל שנות העולם: כיצד? \u0003מתושלח\u0004 עדיין \u0003ראה\u0004 את \u0003אדם\u0004 הראשון, \u0003שם\u0004 בן נח \u0003ראה\u0004 עוד את \u0003מתושלח, יעקב ראה את שם, עמרם\u0004 אבי משה \u0003ראה את יעקב, אחיה השילוני\u0004 שנתנבא בימי ירבעם \u0003ראה את עמרם, אליהו ראה את אחיה השילוני, ועדיין\u0004 הוא \u0003קיים.\u0004","ושואלים: \u0003ואחיה השילוני ראה את עמרם? והא כתיב\u0004 \u0005[והרי נאמר]\u0006 ביוצאי מצרים: \u0003\"ולא נותר מהם איש כי אם כלב בן יפנה ויהושע בן נון\"\u0004 (במדבר כו, סה), ואף אחיה השילוני בכלל אותו הדור היה!","\u0003אמר רב המנונא: לא נגזרה גזרה\u0004 של מיתה בעקבות חטא המרגלים \u0003על שבטו של לוי, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"במדבר הזה יפלו פגריכם וכל פקדיכם לכל מספרכם מבן עשרים שנה ומעלה\"\u0004 (במדבר יד, כט), לומר: \u0003מי שפקודיו\u0004 (שבט שמונים את בניו) \u0003מבן עשרים\u0004 שנה הוא בכלל גזירה זו, \u0003יצא שבטו של לוי שפקודיו מבן שלשים\u0004 שנה (במדבר ד, ג), ואחיה השילוני משבט לוי היה.","ושואלים: \u0003ומשאר שבטים לא עייל\u0004 \u0005[נכנסו]\u0006 לארץ? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יאיר בן מנשה ומכיר בן מנשה נולדו בימי יעקב, ולא מתו עד שנכנסו ישראל לארץ, שנאמר: \"ויכו מהם אנשי העי כשלשים וששה איש\"\u0004 (יהושע ז, ה), \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003שלשים וששה\u0004 איש \u0003ממש\u0004 נהרגו, אלו \u0003דברי\u0004 \u0003ר' יהודה.\u0004","\u0003אמר לו\u0004 \u0003ר' נחמיה: וכי נאמר \"שלשים וששה\"? והלא לא נאמר אלא \"כשלשים וששה\"! אלא\u0004 משמע שאין הכוונה למספר אנשים, אלא לרמז כי \u0003זה יאיר בן מנשה, ששקול כרובה של סנהדרין,\u0004 שהרי מנין חכמי הסנהדרין הגדולה היה שבעים איש, ורובה של סנהדרין הוא איפוא שלושים וששה. ואם כן נותרו מיוצאי מצרים שנכנסו לארץ!","\u0003אלא אמר רב אחא בר יעקב: לא נגזרה גזירה לא על\u0004 מי שהיה \u0003פחות מבן עשרים\u0004 שנה באותו זמן \u0003ולא על\u0004 מי שהיה אז \u0003יתר מבן ששים; לא על פחות מבן עשרים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מבן עשרים שנה ומעלה\"\u0004 (ראה במדבר ד, ג), \u0003ולא על יתר מבן ששים\u0004 — \u0003גמר\u0004 \u0005[למד]\u0006 מגזירה שווה \u0003\"\u0004מבן עשרים שנה \u0003ומעלה\"\u0004 הנאמר בגזירת המרגלים, ו\u0003\"\u0004אם מבן ששים שנה \u0003ומעלה\"\u0004 (ויקרא כז, ז) \u0003מ\u0004הנאמר בפרשת \u0003ערכין, מה להלן\u0004 בערכין \u0003יתר מבן ששים\u0004 \u0003כפחות מבן עשרים,\u0004 שאין דינם כבן מי שהוא מבן עשרים עד בן ששים, \u0003אף כאן\u0004 — \u0003יתר מבן ששים כפחות מבן עשרים\u0004 ולא נגזרה עליו גזירה, ויאיר בן מנשה כבר היה בן ששים כשיצא ממצרים.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003ארץ ישראל לשבטים איפלוג\u0004 \u0005[נתחלקה],\u0006 שחלקו אותה כל השבטים שווה בשווה, ובני השבט היו מתחלקים ביניהם לפי מספרם, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003לקרקף גברי איפלוג\u0004 \u0005[לגולגלות האנשים נחלקה]\u0006 וכל שבט קיבל נחלה לפי מספר אנשיו?"]]};
